insert into public.board_exam_questions (board, contest_name, career_name, exam_year, exam_date, exam_type, item_number, subject, support_text, stem, options, official_answer, needs_visual, legal_review_required, state, career_category, source_url, answer_key_url, review_note) values
('FGV','Controladoria-Geral do Estado de Santa Catarina','Auditor do Estado – Direito',2022,null,'Tipo 1',1,'Língua Portuguesa',null,'Assinale a expressão que caracteriza mais a oralidade que a linguagem informal.','{"A": "a gente.", "B": "de orelha em pé.", "C": "badalada.", "D": "altos salários.", "E": "então."}'::jsonb,'E',false,false,'SC','Controle','https://conhecimento.fgv.br/sites/default/files/concursos/cns104_-_auditor_do_estado_-_direito_manhacns104_tipo_1.pdf','https://conhecimento.fgv.br/sites/default/files/concursos/cgesc2022_gabarito_definitivo_retificado_20230327.pdf','disciplina atribuída pela ordem do caderno'),
('FGV','Controladoria-Geral do Estado de Santa Catarina','Auditor do Estado – Direito',2022,null,'Tipo 1',2,'Língua Portuguesa',null,'Assinale a frase mais proximamente ligada ao texto injuntivo.','{"A": "Quando a gente fala em auditoria, muita gente fica de orelha em pé.", "B": "A profissão é bastante badalada no mercado de trabalho e geralmente associada a altos salários.", "C": "No serviço público, então, é um dos cargos mais desejados!", "D": "Mas você sabe qual são as atribuições desses profissionais? Quanto eles ganham? Onde trabalham?", "E": "Descubra o que faz um auditor e o que estudar para se tornar um!"}'::jsonb,'E',false,false,'SC','Controle','https://conhecimento.fgv.br/sites/default/files/concursos/cns104_-_auditor_do_estado_-_direito_manhacns104_tipo_1.pdf','https://conhecimento.fgv.br/sites/default/files/concursos/cgesc2022_gabarito_definitivo_retificado_20230327.pdf','disciplina atribuída pela ordem do caderno'),
('FGV','Controladoria-Geral do Estado de Santa Catarina','Auditor do Estado – Direito',2022,null,'Tipo 1',3,'Língua Portuguesa','No mercado encontramos vários tipos de auditor. Entre as empresas, o interno e o externo são os mais comuns. Auditor interno? É o profissional contratado pela própria empresa para analisar e garantir o cumprimento dos regulamentos internos. Eles devem identificar falhas ou atestar se os procedimentos internos são cumpridos à risca, buscando sempre um altíssimo padrão de qualidade. Auditor externo? Trabalha em um escritório especializado em auditoria e é chamado para atestar os dados patrimoniais e financeiros da empresa contratante. Por lei, empresas de grande porte (faturamento acima de R$ 300 milhões anuais) e empresas de capital aberto precisam se submeter a um processo anual de auditoria externa. Bancos, seguradoras, fundos de investimento e demais instituições financeiras devem obrigatoriamente passar por uma auditoria a cada seis meses.','O fragmento textual, retirado de um site sobre carreiras, mostra distintas marcas em sua estruturação. Assinale a marca acompanhada de um exemplo do texto, corretamente identificada.','{"A": "Paralelismo sintático: É o profissional contratado pela própria empresa para analisar e garantir o cumprimento dos regulamentos internos.", "B": "Enumeração de termos: Bancos, seguradoras, fundos de investimento e demais instituições financeiras devem obrigatoriamente passar por uma auditoria a cada seis meses.", "C": "Construção pleonástica: Por lei, empresas de grande porte (faturamento acima de R$ 300 milhões anuais) e empresas de capital aberto precisam se submeter a um processo anual de auditoria externa.", "D": "Apelo a uma citação: Por lei, empresas de grande porte (faturamento acima de R$ 300 milhões anuais) e empresas de capital aberto precisam se submeter a um processo anual de auditoria externa.", "E": "Introdução por referência histórica: No mercado encontramos vários tipos de auditor. Entre as empresas, o interno e o externo são os mais comuns."}'::jsonb,'B',false,false,'SC','Controle','https://conhecimento.fgv.br/sites/default/files/concursos/cns104_-_auditor_do_estado_-_direito_manhacns104_tipo_1.pdf','https://conhecimento.fgv.br/sites/default/files/concursos/cgesc2022_gabarito_definitivo_retificado_20230327.pdf','disciplina atribuída pela ordem do caderno'),
('FGV','Controladoria-Geral do Estado de Santa Catarina','Auditor do Estado – Direito',2022,null,'Tipo 1',4,'Língua Portuguesa','No mercado encontramos vários tipos de auditor. Entre as empresas, o interno e o externo são os mais comuns. Auditor interno? É o profissional contratado pela própria empresa para analisar e garantir o cumprimento dos regulamentos internos. Eles devem identificar falhas ou atestar se os procedimentos internos são cumpridos à risca, buscando sempre um altíssimo padrão de qualidade. Auditor externo? Trabalha em um escritório especializado em auditoria e é chamado para atestar os dados patrimoniais e financeiros da empresa contratante. Por lei, empresas de grande porte (faturamento acima de R$ 300 milhões anuais) e empresas de capital aberto precisam se submeter a um processo anual de auditoria externa. Bancos, seguradoras, fundos de investimento e demais instituições financeiras devem obrigatoriamente passar por uma auditoria a cada seis meses.','Na frase “É o profissional contratado pela própria empresa para analisar e garantir o cumprimento dos regulamentos internos”, há dois infinitivos sublinhados. Se essa frase for reescrita, substituindo esses infinitivos por formas nominais, a forma adequada será:','{"A": "É o profissional contratado pela própria empresa para a análise e garantia do cumprimento dos regulamentos internos", "B": "É o profissional contratado pela própria empresa para que analise e garanta o cumprimento dos regulamentos internos", "C": "É o profissional contratado pela própria empresa para a análise e para garantir o cumprimento dos regulamentos internos", "D": "É o profissional contratado pela própria empresa para analisar e para a garantia do cumprimento dos regulamentos internos", "E": "É o profissional contratado pela própria empresa para que se analise e se garanta o cumprimento dos regulamentos internos"}'::jsonb,'A',false,false,'SC','Controle','https://conhecimento.fgv.br/sites/default/files/concursos/cns104_-_auditor_do_estado_-_direito_manhacns104_tipo_1.pdf','https://conhecimento.fgv.br/sites/default/files/concursos/cgesc2022_gabarito_definitivo_retificado_20230327.pdf','disciplina atribuída pela ordem do caderno'),
('FGV','Controladoria-Geral do Estado de Santa Catarina','Auditor do Estado – Direito',2022,null,'Tipo 1',5,'Língua Portuguesa',null,'Observe o seguinte texto: “A auditoria ambiental é uma ferramenta de gestão ambiental definida pela norma NBR ISO 14.010 como um “processo sistemático e documentado de verificação, executado para obter e avaliar, de forma objetiva, evidências de auditoria para determinar se as atividades, eventos, sistemas de gestão e condições ambientais específicos ou as informações relacionadas a estes estão em conformidade com os critérios de auditoria e para comunicar os resultados deste processo ao cliente”. Assim, é considerado um procedimento realizado por profissionais técnicos ou empresas terceirizadas, gerido por um auditor líder e executado por uma equipe preparada, visando avaliar o desempenho e o comprometimento ambiental de empresas e indústrias.” (Auditoria ambiental – M.C.R.Manzano) O texto começa por uma definição do que é “auditoria ambiental”. Assinale a afirmação incorreta sobre a forma dessa definição.','{"A": "Uma definição se inicia sempre por um vocábulo de conteúdo geral que, nesse caso, é “ferramenta”.", "B": "Após o termo geral, há uma especificação de seu significado que, nesse caso, é “de gestão ambiental”.", "C": "Dentro da definição inicial ocorre a presença de uma segunda definição mais específica do termo inicial.", "D": "A indicação da norma legal tem a função de garantir a existência desse tipo de auditoria.", "E": "Após o texto da segunda definição, há uma maior explicitação dos termos da definição legal."}'::jsonb,'D',false,false,'SC','Controle','https://conhecimento.fgv.br/sites/default/files/concursos/cns104_-_auditor_do_estado_-_direito_manhacns104_tipo_1.pdf','https://conhecimento.fgv.br/sites/default/files/concursos/cgesc2022_gabarito_definitivo_retificado_20230327.pdf','disciplina atribuída pela ordem do caderno'),
('FGV','Controladoria-Geral do Estado de Santa Catarina','Auditor do Estado – Direito',2022,null,'Tipo 1',6,'Língua Portuguesa','“Quando deve ocorrer uma auditoria empresarial? É preciso se livrar da convicção de que uma auditoria só é necessária quando as coisas não vão bem – porque ela deve ser feita quando está tudo bem, quando tudo está em perfeitas condições, pois isso pode garantir a ordem nos negócios a longo prazo Quanto maior a empresa, mais provável é que os pontos-chave exijam auditorias completas e frequentes – isso pode ser feito por especialistas internos qualificados ou consultores externos. Para determinar se sua empresa precisa de uma auditoria, considere se as informações em uma área específica são suficientemente transparentes, claras e seguras. Se não, definitivamente indica a necessidade de uma análise aprofundada. Outra orientação muito importante é conversar com os funcionários. Eles sabem melhor do que ninguém se os processos são seguidos e se os requisitos burocráticos e legais são cumpridos. Portanto, comece uma conversa.” (Redator Ponto Tel / 20/10/2021)','Sobre a pergunta que dá título ao texto, é correto afirmar que a resposta a ela dada','{"A": "afirma a necessidade de solicitar aos funcionários a permissão de realizar-se uma auditoria válida.", "B": "contraria uma ideia amplamente aceita.", "C": "aconselha a realização de auditorias quando as informações de uma área específica são transparentes, claras e precisas.", "D": "mostra a geral desinformação sobre o tema.", "E": "indica que há necessidade de auditoria mesmo que as coisas não vão bem na empresa."}'::jsonb,'B',false,false,'SC','Controle','https://conhecimento.fgv.br/sites/default/files/concursos/cns104_-_auditor_do_estado_-_direito_manhacns104_tipo_1.pdf','https://conhecimento.fgv.br/sites/default/files/concursos/cgesc2022_gabarito_definitivo_retificado_20230327.pdf','disciplina atribuída pela ordem do caderno'),
('FGV','Controladoria-Geral do Estado de Santa Catarina','Auditor do Estado – Direito',2022,null,'Tipo 1',7,'Língua Portuguesa','“Quando deve ocorrer uma auditoria empresarial? É preciso se livrar da convicção de que uma auditoria só é necessária quando as coisas não vão bem – porque ela deve ser feita quando está tudo bem, quando tudo está em perfeitas condições, pois isso pode garantir a ordem nos negócios a longo prazo Quanto maior a empresa, mais provável é que os pontos-chave exijam auditorias completas e frequentes – isso pode ser feito por especialistas internos qualificados ou consultores externos. Para determinar se sua empresa precisa de uma auditoria, considere se as informações em uma área específica são suficientemente transparentes, claras e seguras. Se não, definitivamente indica a necessidade de uma análise aprofundada. Outra orientação muito importante é conversar com os funcionários. Eles sabem melhor do que ninguém se os processos são seguidos e se os requisitos burocráticos e legais são cumpridos. Portanto, comece uma conversa.” (Redator Ponto Tel / 20/10/2021)','Em todos os segmentos abaixo há a presença de dois termos sublinhados. Assinale a opção em que a presença do segundo termo é dispensável, por ser sinônimo perfeito do primeiro.','{"A": "porque ela deve ser feita quando está tudo bem, quando tudo está em perfeitas condições.", "B": "mais provável é que os pontos-chave exijam auditorias completas e frequentes.", "C": "isso pode ser feito por especialistas internos qualificados ou consultores externos.", "D": "as informações em uma área específica são suficientemente transparentes, claras e seguras.", "E": "Eles sabem melhor do que ninguém se os processos são seguidos e se os requisitos burocráticos e legais são cumpridos."}'::jsonb,'A',false,false,'SC','Controle','https://conhecimento.fgv.br/sites/default/files/concursos/cns104_-_auditor_do_estado_-_direito_manhacns104_tipo_1.pdf','https://conhecimento.fgv.br/sites/default/files/concursos/cgesc2022_gabarito_definitivo_retificado_20230327.pdf','disciplina atribuída pela ordem do caderno'),
('FGV','Controladoria-Geral do Estado de Santa Catarina','Auditor do Estado – Direito',2022,null,'Tipo 1',8,'Língua Portuguesa','“Quando deve ocorrer uma auditoria empresarial? É preciso se livrar da convicção de que uma auditoria só é necessária quando as coisas não vão bem – porque ela deve ser feita quando está tudo bem, quando tudo está em perfeitas condições, pois isso pode garantir a ordem nos negócios a longo prazo Quanto maior a empresa, mais provável é que os pontos-chave exijam auditorias completas e frequentes – isso pode ser feito por especialistas internos qualificados ou consultores externos. Para determinar se sua empresa precisa de uma auditoria, considere se as informações em uma área específica são suficientemente transparentes, claras e seguras. Se não, definitivamente indica a necessidade de uma análise aprofundada. Outra orientação muito importante é conversar com os funcionários. Eles sabem melhor do que ninguém se os processos são seguidos e se os requisitos burocráticos e legais são cumpridos. Portanto, comece uma conversa.” (Redator Ponto Tel / 20/10/2021)','Em todas as frases abaixo há a presença do vocábulo SE, sublinhado. Assinale a frase em que a função desse vocábulo é diferente da função presente nas demais frases.','{"A": "... considere se as informações em uma área específica são suficientemente transparentes, claras e seguras.", "B": "Para determinar se sua empresa precisa de uma auditoria.", "C": "É preciso se livrar da convicção de que uma auditoria só é necessária quando as coisas não vão bem", "D": "Eles sabem melhor do que ninguém se os processos são seguidos.", "E": "...e se os requisitos burocráticos e legais são cumpridos."}'::jsonb,'C',false,false,'SC','Controle','https://conhecimento.fgv.br/sites/default/files/concursos/cns104_-_auditor_do_estado_-_direito_manhacns104_tipo_1.pdf','https://conhecimento.fgv.br/sites/default/files/concursos/cgesc2022_gabarito_definitivo_retificado_20230327.pdf','disciplina atribuída pela ordem do caderno'),
('FGV','Controladoria-Geral do Estado de Santa Catarina','Auditor do Estado – Direito',2022,null,'Tipo 1',9,'Língua Portuguesa','“Estamos em 2022 e, neste momento, a maioria das transações bancárias, segundo o Banco Central, é realizada na modalidade Pix. Essa modalidade já superou a TED e o DOC. Sabemos que no Brasil existe muita sonegação, muitas empresas, principalmente as menores, não declaram tudo aquilo que movimentam. Porém, do outro lado da mesa, está a Receita Federal — com supercomputadores e com analistas bem treinados para auditar as milhares de informações que chegam aos bancos de dados do órgão. As Secretarias de Fazenda Estaduais e as Prefeituras estão se modernizando cada vez mais (é o caso do DF, que possui a Malha Fiscal), com o uso de tecnologia para tratamento das informações recebidas através das obrigações acessórias, a fim de evitar a sonegação fiscal por parte das empresas e não deixar de arrecadar tributos. A Receita Federal, através do sistema SPED (Sistema Público de Escrituração Digital), montou uma verdadeira armadilha para as pessoas físicas e jurídicas que não declaram suas movimentações financeiras. O que antes era feito em papel passou a ser digital e online, ou seja, hoje em dia a Receita Federal pode identificar uma operação clandestina antes mesmo de ser concluída. E, a partir de 2023, será possível cruzar a movimentação bancária gerada pelas empresas (de qualquer porte) com as informações repassadas pelas instituições financeiras, intermediadores financeiros e instituições de pagamento para arrecadar os tributos devidos nessas operações. Não importa a forma de transferência utilizada pelas empresas, TED, DOC, Pix etc. Tudo será informado para o fisco e, como já dissemos, no caso do Pix, a informação será retroativa.” (Arvi Consultoria)','Observe o primeiro parágrafo desse texto: “Estamos em 2022 e, neste momento, a maioria das transações bancárias, segundo o Banco Central, é realizada na modalidade Pix. Essa modalidade já superou a TED e o DOC.” Sua função textual é a de','{"A": "informar aos leitores menos avisados sobre as diversas modalidades de operações financeiras.", "B": "destacar a importância do Pix como operação financeira, no momento em que vivemos.", "C": "mostrar o descrédito de algumas modalidades de operações financeiras diante do sucesso do Pix.", "D": "antecipar alguns perigos advindos da grande movimentação financeira por meio do Pix.", "E": "localizar uma discussão no momento presente, a fim de mostrar a atualização das instituições no processo de fiscalização."}'::jsonb,'B',false,false,'SC','Controle','https://conhecimento.fgv.br/sites/default/files/concursos/cns104_-_auditor_do_estado_-_direito_manhacns104_tipo_1.pdf','https://conhecimento.fgv.br/sites/default/files/concursos/cgesc2022_gabarito_definitivo_retificado_20230327.pdf','disciplina atribuída pela ordem do caderno'),
('FGV','Controladoria-Geral do Estado de Santa Catarina','Auditor do Estado – Direito',2022,null,'Tipo 1',10,'Língua Portuguesa','“Estamos em 2022 e, neste momento, a maioria das transações bancárias, segundo o Banco Central, é realizada na modalidade Pix. Essa modalidade já superou a TED e o DOC. Sabemos que no Brasil existe muita sonegação, muitas empresas, principalmente as menores, não declaram tudo aquilo que movimentam. Porém, do outro lado da mesa, está a Receita Federal — com supercomputadores e com analistas bem treinados para auditar as milhares de informações que chegam aos bancos de dados do órgão. As Secretarias de Fazenda Estaduais e as Prefeituras estão se modernizando cada vez mais (é o caso do DF, que possui a Malha Fiscal), com o uso de tecnologia para tratamento das informações recebidas através das obrigações acessórias, a fim de evitar a sonegação fiscal por parte das empresas e não deixar de arrecadar tributos. A Receita Federal, através do sistema SPED (Sistema Público de Escrituração Digital), montou uma verdadeira armadilha para as pessoas físicas e jurídicas que não declaram suas movimentações financeiras. O que antes era feito em papel passou a ser digital e online, ou seja, hoje em dia a Receita Federal pode identificar uma operação clandestina antes mesmo de ser concluída. E, a partir de 2023, será possível cruzar a movimentação bancária gerada pelas empresas (de qualquer porte) com as informações repassadas pelas instituições financeiras, intermediadores financeiros e instituições de pagamento para arrecadar os tributos devidos nessas operações. Não importa a forma de transferência utilizada pelas empresas, TED, DOC, Pix etc. Tudo será informado para o fisco e, como já dissemos, no caso do Pix, a informação será retroativa.” (Arvi Consultoria)','“Estamos em 2022 e, neste momento, a maioria das transações bancárias, segundo o Banco Central, é realizada na modalidade Pix. Essa modalidade já superou a TED e o DOC.” Sobre a estruturação sintática e semântica desse primeiro parágrafo do texto, assinale a afirmação correta.','{"A": "A forma verbal “estamos” se refere apenas ao conjunto de leitores do texto.", "B": "No termo “neste”, a forma do demonstrativo utilizada se prende ao fato de o momento estar anunciado antes.", "C": "A expressão “a maioria das transações bancárias” pode levar o verbo da frase também para o plural.", "D": "O termo “segundo o Banco Central” indica a falta de credibilidade dos autores do texto.", "E": "No termo “a TED e o DOC” há um erro gramatical no emprego do primeiro artigo."}'::jsonb,'C',false,false,'SC','Controle','https://conhecimento.fgv.br/sites/default/files/concursos/cns104_-_auditor_do_estado_-_direito_manhacns104_tipo_1.pdf','https://conhecimento.fgv.br/sites/default/files/concursos/cgesc2022_gabarito_definitivo_retificado_20230327.pdf','disciplina atribuída pela ordem do caderno'),
('FGV','Controladoria-Geral do Estado de Santa Catarina','Auditor do Estado – Direito',2022,null,'Tipo 1',11,'Língua Portuguesa','“Estamos em 2022 e, neste momento, a maioria das transações bancárias, segundo o Banco Central, é realizada na modalidade Pix. Essa modalidade já superou a TED e o DOC. Sabemos que no Brasil existe muita sonegação, muitas empresas, principalmente as menores, não declaram tudo aquilo que movimentam. Porém, do outro lado da mesa, está a Receita Federal — com supercomputadores e com analistas bem treinados para auditar as milhares de informações que chegam aos bancos de dados do órgão. As Secretarias de Fazenda Estaduais e as Prefeituras estão se modernizando cada vez mais (é o caso do DF, que possui a Malha Fiscal), com o uso de tecnologia para tratamento das informações recebidas através das obrigações acessórias, a fim de evitar a sonegação fiscal por parte das empresas e não deixar de arrecadar tributos. A Receita Federal, através do sistema SPED (Sistema Público de Escrituração Digital), montou uma verdadeira armadilha para as pessoas físicas e jurídicas que não declaram suas movimentações financeiras. O que antes era feito em papel passou a ser digital e online, ou seja, hoje em dia a Receita Federal pode identificar uma operação clandestina antes mesmo de ser concluída. E, a partir de 2023, será possível cruzar a movimentação bancária gerada pelas empresas (de qualquer porte) com as informações repassadas pelas instituições financeiras, intermediadores financeiros e instituições de pagamento para arrecadar os tributos devidos nessas operações. Não importa a forma de transferência utilizada pelas empresas, TED, DOC, Pix etc. Tudo será informado para o fisco e, como já dissemos, no caso do Pix, a informação será retroativa.” (Arvi Consultoria)','“Sabemos que no Brasil existe muita sonegação, muitas empresas, principalmente as menores, não declaram tudo aquilo que movimentam. Porém, do outro lado da mesa, está a Receita Federal — com supercomputadores e com analistas bem treinados para auditar as milhares de informações que chegam aos bancos de dados do órgão”. Nesse fragmento do texto observamos que','{"A": "nem todos os delitos são punidos, porque falta modernização tecnológica e dedicação dos funcionários públicos.", "B": "a sonegação fiscal tende a desaparecer no país, em função das providências legais tomadas contra ela.", "C": "a conjunção “porém” faz a oposição, respectivamente, entre a legalidade e a ilegalidade.", "D": "as providências legais aparecem sempre após a verificação de delitos.", "E": "o termo “órgão” se refere ao termo anterior “supercomputadores”."}'::jsonb,'D',false,false,'SC','Controle','https://conhecimento.fgv.br/sites/default/files/concursos/cns104_-_auditor_do_estado_-_direito_manhacns104_tipo_1.pdf','https://conhecimento.fgv.br/sites/default/files/concursos/cgesc2022_gabarito_definitivo_retificado_20230327.pdf','disciplina atribuída pela ordem do caderno'),
('FGV','Controladoria-Geral do Estado de Santa Catarina','Auditor do Estado – Direito',2022,null,'Tipo 1',12,'Língua Portuguesa','“Estamos em 2022 e, neste momento, a maioria das transações bancárias, segundo o Banco Central, é realizada na modalidade Pix. Essa modalidade já superou a TED e o DOC. Sabemos que no Brasil existe muita sonegação, muitas empresas, principalmente as menores, não declaram tudo aquilo que movimentam. Porém, do outro lado da mesa, está a Receita Federal — com supercomputadores e com analistas bem treinados para auditar as milhares de informações que chegam aos bancos de dados do órgão. As Secretarias de Fazenda Estaduais e as Prefeituras estão se modernizando cada vez mais (é o caso do DF, que possui a Malha Fiscal), com o uso de tecnologia para tratamento das informações recebidas através das obrigações acessórias, a fim de evitar a sonegação fiscal por parte das empresas e não deixar de arrecadar tributos. A Receita Federal, através do sistema SPED (Sistema Público de Escrituração Digital), montou uma verdadeira armadilha para as pessoas físicas e jurídicas que não declaram suas movimentações financeiras. O que antes era feito em papel passou a ser digital e online, ou seja, hoje em dia a Receita Federal pode identificar uma operação clandestina antes mesmo de ser concluída. E, a partir de 2023, será possível cruzar a movimentação bancária gerada pelas empresas (de qualquer porte) com as informações repassadas pelas instituições financeiras, intermediadores financeiros e instituições de pagamento para arrecadar os tributos devidos nessas operações. Não importa a forma de transferência utilizada pelas empresas, TED, DOC, Pix etc. Tudo será informado para o fisco e, como já dissemos, no caso do Pix, a informação será retroativa.” (Arvi Consultoria)','“As Secretarias de Fazenda Estaduais e as Prefeituras estão se modernizando cada vez mais (é o caso do DF, que possui a Malha Fiscal), com o uso de tecnologia para tratamento das informações recebidas através das obrigações acessórias, a fim de evitar a sonegação fiscal por parte das empresas e não deixar de arrecadar tributos.” Assinale a observação que está em desacordo com as informações e com a estruturação desse segmento textual.','{"A": "a forma do adjetivo “Estaduais” está errada, pois devia obrigatoriamente concordar com o substantivo “Fazenda”.", "B": "o segmento entre parênteses mostra um exemplo da modernização dos órgãos de fiscalização.", "C": "o termo “uso da tecnologia” indica uma valorização dos processos fiscalizatórios.", "D": "o termo “para tratamento das informações recebidas” equivale a “para que se tratem as informações recebidas”.", "E": "a locução “a fim de” mostra a finalidade das duas orações seguintes."}'::jsonb,'A',false,false,'SC','Controle','https://conhecimento.fgv.br/sites/default/files/concursos/cns104_-_auditor_do_estado_-_direito_manhacns104_tipo_1.pdf','https://conhecimento.fgv.br/sites/default/files/concursos/cgesc2022_gabarito_definitivo_retificado_20230327.pdf','disciplina atribuída pela ordem do caderno'),
('FGV','Controladoria-Geral do Estado de Santa Catarina','Auditor do Estado – Direito',2022,null,'Tipo 1',13,'Língua Portuguesa','“Estamos em 2022 e, neste momento, a maioria das transações bancárias, segundo o Banco Central, é realizada na modalidade Pix. Essa modalidade já superou a TED e o DOC. Sabemos que no Brasil existe muita sonegação, muitas empresas, principalmente as menores, não declaram tudo aquilo que movimentam. Porém, do outro lado da mesa, está a Receita Federal — com supercomputadores e com analistas bem treinados para auditar as milhares de informações que chegam aos bancos de dados do órgão. As Secretarias de Fazenda Estaduais e as Prefeituras estão se modernizando cada vez mais (é o caso do DF, que possui a Malha Fiscal), com o uso de tecnologia para tratamento das informações recebidas através das obrigações acessórias, a fim de evitar a sonegação fiscal por parte das empresas e não deixar de arrecadar tributos. A Receita Federal, através do sistema SPED (Sistema Público de Escrituração Digital), montou uma verdadeira armadilha para as pessoas físicas e jurídicas que não declaram suas movimentações financeiras. O que antes era feito em papel passou a ser digital e online, ou seja, hoje em dia a Receita Federal pode identificar uma operação clandestina antes mesmo de ser concluída. E, a partir de 2023, será possível cruzar a movimentação bancária gerada pelas empresas (de qualquer porte) com as informações repassadas pelas instituições financeiras, intermediadores financeiros e instituições de pagamento para arrecadar os tributos devidos nessas operações. Não importa a forma de transferência utilizada pelas empresas, TED, DOC, Pix etc. Tudo será informado para o fisco e, como já dissemos, no caso do Pix, a informação será retroativa.” (Arvi Consultoria)','Sobre as siglas empregadas no texto – DF, TED, DOC, SPED – assinale a afirmativa incorreta.','{"A": "A sigla DOC corresponde à forma abreviada de “documento”.", "B": "A sigla SPED tem sua explicação entre parênteses por não ser de amplo conhecimento do público.", "C": "As siglas TED e DOC são vistas pelo autor do texto como de amplo conhecimento dos leitores.", "D": "O emprego de siglas traz como uma de suas consequências a economia de espaço gráfico.", "E": "Todas as letras das siglas correspondem a palavras significativas da expressão original."}'::jsonb,'A',true,false,'SC','Controle','https://conhecimento.fgv.br/sites/default/files/concursos/cns104_-_auditor_do_estado_-_direito_manhacns104_tipo_1.pdf','https://conhecimento.fgv.br/sites/default/files/concursos/cgesc2022_gabarito_definitivo_retificado_20230327.pdf','depende de figura, tabela ou gráfico do caderno original: conferir antes de ativar; disciplina atribuída pela ordem do caderno'),
('FGV','Controladoria-Geral do Estado de Santa Catarina','Auditor do Estado – Direito',2022,null,'Tipo 1',14,'Língua Portuguesa','“Estamos em 2022 e, neste momento, a maioria das transações bancárias, segundo o Banco Central, é realizada na modalidade Pix. Essa modalidade já superou a TED e o DOC. Sabemos que no Brasil existe muita sonegação, muitas empresas, principalmente as menores, não declaram tudo aquilo que movimentam. Porém, do outro lado da mesa, está a Receita Federal — com supercomputadores e com analistas bem treinados para auditar as milhares de informações que chegam aos bancos de dados do órgão. As Secretarias de Fazenda Estaduais e as Prefeituras estão se modernizando cada vez mais (é o caso do DF, que possui a Malha Fiscal), com o uso de tecnologia para tratamento das informações recebidas através das obrigações acessórias, a fim de evitar a sonegação fiscal por parte das empresas e não deixar de arrecadar tributos. A Receita Federal, através do sistema SPED (Sistema Público de Escrituração Digital), montou uma verdadeira armadilha para as pessoas físicas e jurídicas que não declaram suas movimentações financeiras. O que antes era feito em papel passou a ser digital e online, ou seja, hoje em dia a Receita Federal pode identificar uma operação clandestina antes mesmo de ser concluída. E, a partir de 2023, será possível cruzar a movimentação bancária gerada pelas empresas (de qualquer porte) com as informações repassadas pelas instituições financeiras, intermediadores financeiros e instituições de pagamento para arrecadar os tributos devidos nessas operações. Não importa a forma de transferência utilizada pelas empresas, TED, DOC, Pix etc. Tudo será informado para o fisco e, como já dissemos, no caso do Pix, a informação será retroativa.” (Arvi Consultoria)','“A Receita Federal, através do sistema SPED (Sistema Público de Escrituração Digital), montou uma verdadeira armadilha para as pessoas físicas e jurídicas que não declaram suas movimentações financeiras.” Nesse segmento do texto, o vocábulo “verdadeira” mostra o mesmo significado que na seguinte frase:','{"A": "Os caixas dos supermercados verificam sempre se as cédulas de alto valor recebidas são verdadeiras.", "B": "As verdadeiras afirmações de Cristo deviam ser ouvidas com mais atenção, pois, não sendo falsas, geram o bem.", "C": "As moedas achadas no navio naufragado são verdadeiras e foram cunhadas no século X.", "D": "Os supercomputadores são verdadeiros espiões contra o crime.", "E": "A única afirmação verdadeira do ministro foi desprezada pelos ouvintes. Fundamentos da Auditoria Governamental"}'::jsonb,'D',false,false,'SC','Controle','https://conhecimento.fgv.br/sites/default/files/concursos/cns104_-_auditor_do_estado_-_direito_manhacns104_tipo_1.pdf','https://conhecimento.fgv.br/sites/default/files/concursos/cgesc2022_gabarito_definitivo_retificado_20230327.pdf','disciplina atribuída pela ordem do caderno'),
('FGV','Controladoria-Geral do Estado de Santa Catarina','Auditor do Estado – Direito',2022,null,'Tipo 1',15,'Auditoria',null,'A Matriz de Planejamento é um instrumento fundamental para o direcionamento e a organização de todo o trabalho de auditoria. Assinale a opção que indica corretamente o componente da matriz de planejamento com a sua respectiva explicação, de acordo com a Instrução Normativa CGE nº 001/2021.','{"A": "Informações requeridas: identificação de onde as informações estão disponíveis.", "B": "Critérios: apresentação de eventuais impedimentos para a realização dos trabalhos.", "C": "Questões de auditoria: descrição daquilo que motivou a auditoria, expresso de forma clara e concisa.", "D": "Subquestões de auditoria: avaliação sobre o objeto auditado, se este atende, excede ou está aquém do desempenho esperado.", "E": "Procedimentos de auditoria: conjunto de exames com a finalidade de obter evidências suficientes, confiáveis, fidedignas, relevantes e úteis, que permitam responder a uma questão de auditoria."}'::jsonb,'E',false,false,'SC','Controle','https://conhecimento.fgv.br/sites/default/files/concursos/cns104_-_auditor_do_estado_-_direito_manhacns104_tipo_1.pdf','https://conhecimento.fgv.br/sites/default/files/concursos/cgesc2022_gabarito_definitivo_retificado_20230327.pdf','disciplina atribuída pela ordem do caderno'),
('FGV','Controladoria-Geral do Estado de Santa Catarina','Auditor do Estado – Direito',2022,null,'Tipo 1',16,'Auditoria',null,'De acordo com a Instrução Normativa CGE nº 001/2021, os trabalhos de auditoria devem ter como objetivo agregar valor à unidade auditada, identificando oportunidades para aperfeiçoamento dos processos de governança, gerenciamento de riscos e de controle dessa unidade. Durante a execução do trabalho de auditoria, eventuais situações de indícios de irregularidades, consideradas sem gravidade e fora do escopo do trabalho, devem ser','{"A": "ignoradas pela equipe de auditoria, uma vez que poderão atrapalhar o foco da equipe e trazer resultados inadequados ao trabalho.", "B": "incorporadas ao escopo do trabalho pela equipe de auditoria, uma vez que o esforço em solucioná-las trará aperfeiçoamento dos processos de governança.", "C": "incorporadas ao escopo do trabalho pela equipe de auditoria, uma vez que, se não forem consideradas, podem comprometer o resultado final do trabalho de auditoria.", "D": "apontadas e reportadas ao superior hierárquico para providências em futuros trabalhos, uma vez que não são de responsabilidade da equipe de auditoria.", "E": "apontadas e reportadas ao superior hierárquico para providências em futuros trabalhos, uma vez que a equipe de auditoria deve manter-se alinhada ao escopo e objetivo definidos previamente na fase do planejamento."}'::jsonb,'E',false,false,'SC','Controle','https://conhecimento.fgv.br/sites/default/files/concursos/cns104_-_auditor_do_estado_-_direito_manhacns104_tipo_1.pdf','https://conhecimento.fgv.br/sites/default/files/concursos/cgesc2022_gabarito_definitivo_retificado_20230327.pdf','disciplina atribuída pela ordem do caderno'),
('FGV','Controladoria-Geral do Estado de Santa Catarina','Auditor do Estado – Direito',2022,null,'Tipo 1',17,'Auditoria',null,'Os achados de auditoria que registram desconformidade com o critério devem ser classificados de acordo com o impacto nos objetivos da unidade auditada. Nesse sentido, a interrupção de operações ou atividades relativas a processos, projetos ou programas que causam impactos significativos, porém recuperáveis, nos objetivos da unidade auditada são classificados no nível','{"A": "baixo.", "B": "médio.", "C": "alto.", "D": "muito alto.", "E": "irrelevante."}'::jsonb,'B',false,false,'SC','Controle','https://conhecimento.fgv.br/sites/default/files/concursos/cns104_-_auditor_do_estado_-_direito_manhacns104_tipo_1.pdf','https://conhecimento.fgv.br/sites/default/files/concursos/cgesc2022_gabarito_definitivo_retificado_20230327.pdf','disciplina atribuída pela ordem do caderno'),
('FGV','Controladoria-Geral do Estado de Santa Catarina','Auditor do Estado – Direito',2022,null,'Tipo 1',18,'Auditoria',null,'Em relação aos papéis de trabalho, analise os exemplos a seguir: I. organograma II. documentos do planejamento III. relatos de visitas ou inspeções realizadas IV. fluxograma de procedimentos operacionais V. relatórios de auditoria de exercícios anteriores VI. solicitações de auditoria e as respectivas respostas Assinale a opção que indica apenas os papéis de trabalho classificados como correntes.','{"A": "I, IV e V.", "B": "I, V e VI.", "C": "II, III e IV.", "D": "II, III e VI.", "E": "II, V e VI."}'::jsonb,'D',true,false,'SC','Controle','https://conhecimento.fgv.br/sites/default/files/concursos/cns104_-_auditor_do_estado_-_direito_manhacns104_tipo_1.pdf','https://conhecimento.fgv.br/sites/default/files/concursos/cgesc2022_gabarito_definitivo_retificado_20230327.pdf','depende de figura, tabela ou gráfico do caderno original: conferir antes de ativar; disciplina atribuída pela ordem do caderno'),
('FGV','Controladoria-Geral do Estado de Santa Catarina','Auditor do Estado – Direito',2022,null,'Tipo 1',19,'Auditoria',null,'Os relatórios de auditoria constituem um meio de comunicação entre auditores e unidades auditadas. Assinale a opção que indica a seção do relatório em que estão registrados os achados de auditoria.','{"A": "Resumo.", "B": "Conclusão.", "C": "Resultado dos exames.", "D": "Recomendações.", "E": "Introdução."}'::jsonb,'C',false,false,'SC','Controle','https://conhecimento.fgv.br/sites/default/files/concursos/cns104_-_auditor_do_estado_-_direito_manhacns104_tipo_1.pdf','https://conhecimento.fgv.br/sites/default/files/concursos/cgesc2022_gabarito_definitivo_retificado_20230327.pdf','disciplina atribuída pela ordem do caderno'),
('FGV','Controladoria-Geral do Estado de Santa Catarina','Auditor do Estado – Direito',2022,null,'Tipo 1',20,'Auditoria',null,'De acordo com a Instrução Normativa CGE nº 001/2021, algumas recomendações podem estabelecer, em função da complexidade e da quantidade de ações a serem realizadas, a necessidade da elaboração de um plano de ação que direcione e permita o acompanhamento da implementação das medidas requeridas. Os planos de ação devem ser elaborados e avaliados, respectivamente, por','{"A": "gestores e equipe de auditoria.", "B": "gestores e proprietário.", "C": "equipe de auditoria e gestores.", "D": "entidade reguladora e gestores.", "E": "equipe de auditoria e proprietário."}'::jsonb,'A',false,false,'SC','Controle','https://conhecimento.fgv.br/sites/default/files/concursos/cns104_-_auditor_do_estado_-_direito_manhacns104_tipo_1.pdf','https://conhecimento.fgv.br/sites/default/files/concursos/cgesc2022_gabarito_definitivo_retificado_20230327.pdf','disciplina atribuída pela ordem do caderno'),
('FGV','Controladoria-Geral do Estado de Santa Catarina','Auditor do Estado – Direito',2022,null,'Tipo 1',21,'Auditoria',null,'O risco de auditoria caracterizado pela possibilidade de o erro acontecer em face da não existência de controle é denominado','{"A": "inerente.", "B": "de controle.", "C": "de detecção.", "D": "organizacional.", "E": "de planejamento."}'::jsonb,'A',false,false,'SC','Controle','https://conhecimento.fgv.br/sites/default/files/concursos/cns104_-_auditor_do_estado_-_direito_manhacns104_tipo_1.pdf','https://conhecimento.fgv.br/sites/default/files/concursos/cgesc2022_gabarito_definitivo_retificado_20230327.pdf','disciplina atribuída pela ordem do caderno'),
('FGV','Controladoria-Geral do Estado de Santa Catarina','Auditor do Estado – Direito',2022,null,'Tipo 1',22,'Auditoria',null,'O propósito da gestão de riscos, de acordo com a ISO 31000, é a criação e proteção de valor. Nesse sentido, uma abordagem estruturada e abrangente para a gestão de riscos contribui para resultados','{"A": "neutros e oportunos.", "B": "completos e verificáveis.", "C": "relevantes e tempestivos.", "D": "consistentes e comparáveis.", "E": "integrados e compreensíveis."}'::jsonb,'D',false,false,'SC','Controle','https://conhecimento.fgv.br/sites/default/files/concursos/cns104_-_auditor_do_estado_-_direito_manhacns104_tipo_1.pdf','https://conhecimento.fgv.br/sites/default/files/concursos/cgesc2022_gabarito_definitivo_retificado_20230327.pdf','disciplina atribuída pela ordem do caderno'),
('FGV','Controladoria-Geral do Estado de Santa Catarina','Auditor do Estado – Direito',2022,null,'Tipo 1',23,'Legislação de Controle Interno',null,'A Lei nº 17.715/2019 institui o Programa de Integridade e Compliance da Administração Pública em todos os órgãos e entidades governamentais no âmbito do Estado de Santa Catarina. Em relação ao Programa de Integridade e Compliance, estão corretas as afirmativas a seguir, à exceção de uma. Assinale-a.','{"A": "Entre os objetivos do programa está fomentar a cultura de controle interno da administração, na busca contínua por sua conformidade, assim como a inovação e a adoção de boas práticas de gestão pública.", "B": "Deve ser concebido e implementado de acordo com o perfil geral dos órgãos e entidades públicas estaduais, de modo que as medidas de proteção nele estabelecidas são implantadas de acordo com o risco generalizado que elas apresentam.", "C": "Seu estabelecimento expressa o comprometimento do Estado de Santa Catarina com o combate à corrupção em todas as formas e contextos, bem como com a integridade, a transparência pública e o controle social.", "D": "Representa o documento oficial do órgão ou entidade que contempla os principais riscos de integridade da organização, as medidas e preceitos de tratamento dos riscos identificados e a forma de implementação em monitoramento do programa.", "E": "Deve ser divulgado, após apresentado e aprovado pelo órgão ou entidade, em página eletrônica interna, sendo permitido o registro de comentários e sugestões, que podem ser utilizados para posterior monitoramento e aprimoramento do Plano."}'::jsonb,'X',false,true,'SC','Controle','https://conhecimento.fgv.br/sites/default/files/concursos/cns104_-_auditor_do_estado_-_direito_manhacns104_tipo_1.pdf','https://conhecimento.fgv.br/sites/default/files/concursos/cgesc2022_gabarito_definitivo_retificado_20230327.pdf','questão ANULADA pela banca; conferir vigência da norma antes de ativar; disciplina atribuída pela ordem do caderno'),
('FGV','Controladoria-Geral do Estado de Santa Catarina','Auditor do Estado – Direito',2022,null,'Tipo 1',24,'Legislação de Controle Interno',null,'De acordo com a Lei Complementar 741/19 e alterações, entre os órgãos superiores da Administração Pública Estadual Direta do Estado de Santa Catarina está a Controladoria-Geral do Estado (CGE). Entre as suas atribuições está','{"A": "expedir e encaminhar para publicação decretos, leis, medidas provisórias e demais atos do processo legislativo emanados pelo Governador do Estado.", "B": "orientar e coordenar o estudo, a produção formal e as adequações jurídicas e técnicas dos atos do processo legislativo a serem submetidos ao Governador do Estado, em articulação com os órgãos e as entidades da Administração Pública Estadual.", "C": "determinar as regras e os procedimentos cerimoniais a serem seguidos pelos órgãos e pelas entidades da Administração Pública Estadual e pelas pessoas jurídicas de direito privado quando estiverem presentes o Governador do Estado ou o Vice-Governador do Estado.", "D": "assistir o Governador do Estado e o Vice-Governador do Estado no desempenho de suas atribuições constitucionais e legais e coordenar as ações referentes à agenda governamental, a audiências, a comunicações, a viagens, a eventos e a cerimônias civis e militares das quais participem.", "E": "tomar as providências necessárias à defesa do patrimônio público, ao controle interno, à auditoria pública, à correição, à prevenção e ao combate à corrupção, às atividades de ouvidoria e ao incremento da transparência da gestão no âmbito da Administração Pública Estadual."}'::jsonb,'E',false,true,'SC','Controle','https://conhecimento.fgv.br/sites/default/files/concursos/cns104_-_auditor_do_estado_-_direito_manhacns104_tipo_1.pdf','https://conhecimento.fgv.br/sites/default/files/concursos/cgesc2022_gabarito_definitivo_retificado_20230327.pdf','conferir vigência da norma antes de ativar; disciplina atribuída pela ordem do caderno'),
('FGV','Controladoria-Geral do Estado de Santa Catarina','Auditor do Estado – Direito',2022,null,'Tipo 1',25,'Legislação de Controle Interno',null,'No modelo das três linhas, cada linha tem seu papel definido, e não há hierarquia entre elas. Em relação ao modelo, relacione a linha a sua respectiva função. 1. Primeira linha 2. Segunda linha 3. Terceira linha ( ) Fornecer expertise e apoio; monitorar a implementação de recomendações; verificar questões relacionadas a riscos; analisar conformidade com as normas, regulamentos e comportamento ético. ( ) Executar atividades de acordo com as normas vigentes; gerenciar riscos; prestar contas aos Secretários Estaduais, Presidentes e Dirigentes das organizações públicas. ( ) Realizar auditorias sobre as atividades realizadas, avaliando a adequação e eficácia da governança e do gerenciamento de riscos; promover a prestação de contas das atividades da auditoria ao Chefe do Poder Executivo. Assinale a opção que indica a relação correta, na ordem apresentada.','{"A": "1 – 2 – 3.", "B": "1 – 3 – 2.", "C": "2 – 1 – 3.", "D": "2 – 3 – 1.", "E": "3 – 1 – 2. Controle na Administração Pública"}'::jsonb,'C',false,true,'SC','Controle','https://conhecimento.fgv.br/sites/default/files/concursos/cns104_-_auditor_do_estado_-_direito_manhacns104_tipo_1.pdf','https://conhecimento.fgv.br/sites/default/files/concursos/cgesc2022_gabarito_definitivo_retificado_20230327.pdf','conferir vigência da norma antes de ativar; disciplina atribuída pela ordem do caderno'),
('FGV','Controladoria-Geral do Estado de Santa Catarina','Auditor do Estado – Direito',2022,null,'Tipo 1',26,'Legislação de Controle Interno',null,'A Lei nº 13.460/2017 estabelece as regras para a participação dos usuários na prestação e avaliação de serviços públicos no âmbito dos conselhos de usuários. Assinale a opção que contém apenas atribuições dos conselhos de usuários previstas na referida lei.','{"A": "Solicitar a prestação de serviços em nome de usuários cuja solicitação esteja inviabilizada e acompanhar a prestação dos serviços.", "B": "Acompanhar a prestação dos serviços e contribuir na definição de diretrizes para o adequado atendimento ao usuário.", "C": "Participar na avaliação dos serviços e solicitar a prestação de serviços em nome de usuários cuja solicitação esteja inviabilizada.", "D": "Contribuir na definição de diretrizes para o adequado atendimento ao usuário e solicitar a prestação de serviços em nome de usuários cuja solicitação esteja inviabilizada.", "E": "Solicitar a prestação de serviços em nome de usuários cuja solicitação esteja inviabilizada e estabelecer critérios para a composição do conselho de usuários."}'::jsonb,'B',false,true,'SC','Controle','https://conhecimento.fgv.br/sites/default/files/concursos/cns104_-_auditor_do_estado_-_direito_manhacns104_tipo_1.pdf','https://conhecimento.fgv.br/sites/default/files/concursos/cgesc2022_gabarito_definitivo_retificado_20230327.pdf','conferir vigência da norma antes de ativar; disciplina atribuída pela ordem do caderno'),
('FGV','Controladoria-Geral do Estado de Santa Catarina','Auditor do Estado – Direito',2022,null,'Tipo 1',27,'Legislação de Controle Interno',null,'A Lei de Acesso à Informação (LAI) regula as condições, processos e procedimentos para a aquisição de informação acerca do funcionamento da União, estados e municípios. Nela estão previstos casos nos quais o acesso a estes dados poderá ser negado e quando é possível recorrer desta decisão. Acerca de recursos à Controladoria-Geral da União no âmbito da LAI, assinale a afirmativa correta.','{"A": "Os recursos podem ocorrer exclusivamente em caso de descumprimento de prazos e procedimentos previstos em lei por entidades municipais, estaduais e federais.", "B": "Os recursos podem ocorrer caso negado o acesso à informação não sigilosa ou à informação sigilosa sem indicação da autoridade classificadora no âmbito do poder executivo federal, estadual ou municipal.", "C": "Os recursos podem ocorrer exclusivamente caso o acesso à informação não classificada como sigilosa for negado por entidade do executivo federal.", "D": "Os recursos podem ocorrer exclusivamente caso os procedimentos de classificação de informação sigilosa estabelecidos em lei não tiverem sido observados no âmbito do poder executivo federal.", "E": "Os recursos podem ocorrer caso negado o acesso à informação não sigilosa ou à informação sigilosa sem indicação da autoridade classificadora no âmbito do poder executivo federal."}'::jsonb,'E',false,true,'SC','Controle','https://conhecimento.fgv.br/sites/default/files/concursos/cns104_-_auditor_do_estado_-_direito_manhacns104_tipo_1.pdf','https://conhecimento.fgv.br/sites/default/files/concursos/cgesc2022_gabarito_definitivo_retificado_20230327.pdf','conferir vigência da norma antes de ativar; disciplina atribuída pela ordem do caderno'),
('FGV','Controladoria-Geral do Estado de Santa Catarina','Auditor do Estado – Direito',2022,null,'Tipo 1',28,'Legislação de Controle Interno',null,'A Lei nº 14.230/2021 altera a Lei nº 8.429/1992 e dispõe sobre as sanções aplicáveis em casos de improbidade administrativa. Acerca das sanções nela previstas, assinale a afirmativa correta.','{"A": "Em caso de ressarcimento integral do dano patrimonial e de sanções penais não cabem outras sanções nas hipóteses dos artigos 9º e 10 da Lei de Improbidade Administrativa.", "B": "Independente do ressarcimento integral do dano patrimonial nas hipóteses dos artigos 9º e 10 da Lei de Improbidade Administrativa cabem a perda dos direitos políticos por até 14 anos e a proibição de contratar com o poder público por até 12 anos, respectivamente.", "C": "Em caso de ressarcimento integral do dano patrimonial ou de sanções penais não cabem outras sanções nas hipóteses dos artigos 9º e 10 da Lei de Improbidade Administrativa.", "D": "Independente do ressarcimento integral do dano patrimonial nas hipóteses dos artigos 10 e 11 da Lei de Improbidade Administrativa cabem a perda dos direitos políticos por até 14 anos e a proibição de contratar com o poder público por até 24 anos, respectivamente.", "E": "Independente do ressarcimento integral do dano patrimonial nas hipóteses dos artigos 9º e 11 da Lei de Improbidade Administrativa cabem a perda dos direitos políticos por até 12 anos e a proibição de contratar com o poder público por até 24 anos, respectivamente."}'::jsonb,'X',false,true,'SC','Controle','https://conhecimento.fgv.br/sites/default/files/concursos/cns104_-_auditor_do_estado_-_direito_manhacns104_tipo_1.pdf','https://conhecimento.fgv.br/sites/default/files/concursos/cgesc2022_gabarito_definitivo_retificado_20230327.pdf','questão ANULADA pela banca; conferir vigência da norma antes de ativar; disciplina atribuída pela ordem do caderno'),
('FGV','Controladoria-Geral do Estado de Santa Catarina','Auditor do Estado – Direito',2022,null,'Tipo 1',29,'Legislação de Controle Interno',null,'O decreto estadual nº 1.933/2022, de Santa Catarina, trata do recebimento de denúncias por via eletrônica no âmbito da ouvidoria do estado. Como forma de resguardo aos denunciantes, o decreto prevê a proteção de seus elementos identificadores. Assinale a opção que contém apenas hipóteses previstas no referido decreto em que elementos identificadores do denunciante poderão ser compartilhados entre unidades distintas.','{"A": "Exclusivamente mediante consentimento do denunciante ou para cumprimento de ordem judicial.", "B": "Mediante requerimento da unidade investigada ou quando indispensável à análise dos fatos na denúncia em entidade distinta da que recebeu a manifestação.", "C": "Mediante consentimento do denunciante ou quando indispensável à análise dos fatos na denúncia.", "D": "Para cumprimento de ordem judicial ou mediante consentimento do titular para entidade distinta da que recebeu a manifestação.", "E": "Exclusivamente para cumprimento de ordem judicial."}'::jsonb,'D',false,true,'SC','Controle','https://conhecimento.fgv.br/sites/default/files/concursos/cns104_-_auditor_do_estado_-_direito_manhacns104_tipo_1.pdf','https://conhecimento.fgv.br/sites/default/files/concursos/cgesc2022_gabarito_definitivo_retificado_20230327.pdf','conferir vigência da norma antes de ativar; disciplina atribuída pela ordem do caderno'),
('FGV','Controladoria-Geral do Estado de Santa Catarina','Auditor do Estado – Direito',2022,null,'Tipo 1',30,'Legislação de Controle Interno',null,'Os conselhos de gestão são espaços de interação direta entre Estado e sociedade. Sobre os conselhos de gestão, analise a afirmativas a seguir. I. São espaços públicos estatais que possibilitam a representação de interesses coletivos na definição da agenda pública. II. Distinguem-se de outras manifestações da sociedade civil, por ser sua estrutura legalmente definida e institucionalizada e por buscar a ação conjunta com o aparato estatal. III. O estatuto jurídico dos conselhos permite uma completa autonomia desse subsistema em relação à economia e à política. Está correto apenas o que se afirma em','{"A": "I.", "B": "II.", "C": "III.", "D": "I e II.", "E": "II e III."}'::jsonb,'B',false,true,'SC','Controle','https://conhecimento.fgv.br/sites/default/files/concursos/cns104_-_auditor_do_estado_-_direito_manhacns104_tipo_1.pdf','https://conhecimento.fgv.br/sites/default/files/concursos/cgesc2022_gabarito_definitivo_retificado_20230327.pdf','conferir vigência da norma antes de ativar; disciplina atribuída pela ordem do caderno'),
('FGV','Controladoria-Geral do Estado de Santa Catarina','Auditor do Estado – Direito',2022,null,'Tipo 1',31,'Legislação de Controle Interno',null,'O decreto nº 913/2012 do estado de Santa Catarina estabelece o portal da transparência como o canal oficial do poder executivo estadual. Nele constam informações sobre as atividades exercidas pelo governo do estado sob responsabilidade da Diretoria de Contabilidade Geral (DCOG) da Secretaria de Estado da Fazenda. Sobre as informações disponíveis no portal, é correto afirmar que','{"A": "são publicados todos os atos praticados na execução da despesa, no momento de sua realização, com dados da pessoa física ou jurídica beneficiária do pagamento anonimizada.", "B": "são publicados o lançamento e o recebimento de toda a receita, exceto os referentes a recursos extraorçamentários.", "C": "são publicados todos os atos praticados na execução da despesa, no momento de sua realização, com dados referentes ao número do correspondente processo.", "D": "são publicados os procedimentos licitatórios já concluídos, exceto os relativos à dispensa ou inexigibilidade de licitação.", "E": "são publicadas informações relativas à implementação e resultados apenas de programas e projetos já concluídos."}'::jsonb,'C',false,true,'SC','Controle','https://conhecimento.fgv.br/sites/default/files/concursos/cns104_-_auditor_do_estado_-_direito_manhacns104_tipo_1.pdf','https://conhecimento.fgv.br/sites/default/files/concursos/cgesc2022_gabarito_definitivo_retificado_20230327.pdf','conferir vigência da norma antes de ativar; disciplina atribuída pela ordem do caderno'),
('FGV','Controladoria-Geral do Estado de Santa Catarina','Auditor do Estado – Direito',2022,null,'Tipo 1',32,'Legislação de Controle Interno',null,'Accountability é parte fundamental do papel dos conselhos de gestão e tem como principal finalidade o controle do poder e da autoridade estatal. Sobre a accountability, em relação aos conselhos de gestão, assinale a afirmativa correta.','{"A": "Os conselhos de gestão representam uma forma de accountability societal, um mecanismo de controle não- eleitoral com ferramentas institucionais e não institucionais baseadas na ação de cidadãos.", "B": "Os conselhos de gestão representam uma forma de accountability horizontal, um mecanismo de controle estatal baseado em uma rede de agências internas ao Estado que visam estabelecer checks and balances.", "C": "Os conselhos de gestão representam uma forma de accountability horizontal, um mecanismo de controle não- eleitoral com ferramentas institucionais e não institucionais baseadas na ação de cidadãos.", "D": "Os conselhos de gestão representam uma forma de accountability vertical, um mecanismo de controle eleitoral com ferramentas institucionais e não institucionais baseadas na ação de cidadãos.", "E": "Os conselhos de gestão representam uma forma de accountability vertical, um mecanismo de controle não- eleitoral com ferramentas institucionais e não institucionais baseadas na ação de cidadãos. Direito Constitucional"}'::jsonb,'A',false,true,'SC','Controle','https://conhecimento.fgv.br/sites/default/files/concursos/cns104_-_auditor_do_estado_-_direito_manhacns104_tipo_1.pdf','https://conhecimento.fgv.br/sites/default/files/concursos/cgesc2022_gabarito_definitivo_retificado_20230327.pdf','conferir vigência da norma antes de ativar; disciplina atribuída pela ordem do caderno'),
('FGV','Controladoria-Geral do Estado de Santa Catarina','Auditor do Estado – Direito',2022,null,'Tipo 1',33,'Direito Constitucional',null,'O Presidente da República editou quatro medidas provisórias (MPs), cada qual com o seguinte objeto: (1ª MP) autorizou que os Estados e o Distrito Federal legislassem sobre sistema de consórcios e sorteios em seu território; (2ª MP) alterou a alíquota de certo imposto de competência da União; (3ª MP) abriu créditos extraordinários ao orçamento da União, com o objetivo de atender a despesas imprevisíveis e urgentes decorrentes de comoção interna; e (4ª MP) alterou as regras do processo disciplinar dos servidores públicos civis da União. O Partido Político Alfa, insatisfeito com a edição das medidas provisórias, consultou o seu advogado a respeito da compatibilidade formal desses diplomas normativos com a ordem constitucional, considerando o objeto de cada qual. O advogado, abstendo-se de considerações em torno de sua relevância e urgência, respondeu corretamente que, sob a ótica formal,','{"A": "apenas a 2ª, a 3ª e a 4ª medidas provisórias são constitucionais.", "B": "apenas a 1ª e a 4ª medidas provisórias são constitucionais.", "C": "apenas a 2ª e a 3ª medidas provisórias são constitucionais.", "D": "todas as medidas provisórias são constitucionais.", "E": "apenas a 2ª medida provisória é constitucional."}'::jsonb,'A',false,true,'SC','Controle','https://conhecimento.fgv.br/sites/default/files/concursos/cns104_-_auditor_do_estado_-_direito_manhacns104_tipo_1.pdf','https://conhecimento.fgv.br/sites/default/files/concursos/cgesc2022_gabarito_definitivo_retificado_20230327.pdf','conferir vigência da norma antes de ativar; disciplina atribuída pela ordem do caderno'),
('FGV','Controladoria-Geral do Estado de Santa Catarina','Auditor do Estado – Direito',2022,null,'Tipo 1',34,'Direito Constitucional',null,'Determinado diploma normativo editado pela União dispôs que era vedada a adesão, a certo regime tributário diferenciado, pela microempresa e pela empresa de pequeno porte que possuíssem débito com as Fazendas Públicas Federal, Estadual ou Municipal. Irresignado com o teor desse diploma normativo, o Partido Político Alfa, que defendia, como principal ideologia, o liberalismo econômico, consultou um advogado a respeito de sua compatibilidade com os princípios gerais da atividade econômica consagrados na Constituição da República de 1988. O advogado respondeu corretamente a Alfa que a parte do diploma normativo descrita na narrativa é','{"A": "inconstitucional, pois configura verdadeira “sanção política”, tratando-se de meio indireto de cobrança de tributos que afronta a igualdade que deve caracterizar a exploração da atividade econômica.", "B": "inconstitucional, pois é ilícita a imposição de qualquer restrição ou condicionamento ao exercício da atividade econômica, além daquelas expressamente previstas na ordem constitucional.", "C": "inconstitucional, pois a ordem constitucional assegura o tratamento diferenciado das empresas de pequeno porte que tenham sua sede e administração no País, as quais devem ser excluídas do alcance do diploma normativo.", "D": "constitucional, pois o exercício da atividade econômica por operadores privados sempre pressupõe autorização do Poder Público, logo, não há óbice em restringir benefícios ao seu exercício nas hipóteses de afronta à juridicidade.", "E": "constitucional, pois, longe de afrontar a livre concorrência, impede que pessoas jurídicas que infrinjam as leis fiscais possam se beneficiar de um regime tributário diferenciado, o que lhes daria melhores condições de atuar no mercado."}'::jsonb,'E',true,true,'SC','Controle','https://conhecimento.fgv.br/sites/default/files/concursos/cns104_-_auditor_do_estado_-_direito_manhacns104_tipo_1.pdf','https://conhecimento.fgv.br/sites/default/files/concursos/cgesc2022_gabarito_definitivo_retificado_20230327.pdf','depende de figura, tabela ou gráfico do caderno original: conferir antes de ativar; conferir vigência da norma antes de ativar; disciplina atribuída pela ordem do caderno'),
('FGV','Controladoria-Geral do Estado de Santa Catarina','Auditor do Estado – Direito',2022,null,'Tipo 1',35,'Direito Constitucional',null,'Joana, estudante de direito, solicitou que Ana, sua colega, lhe explicasse algumas características das competências recursais do Supremo Tribunal Federal. De acordo com Ana: 1. os recursos de competência do Supremo Tribunal Federal são apenas os de fundamentação vinculada; 2. nenhuma sentença proferida por órgão jurisdicional de primeira instância pode ser objeto de recurso a ser julgado diretamente pelo Supremo Tribunal Federal; e 3. acórdãos proferidos pelos Tribunais Superiores não podem ser objeto de recurso direcionado ao Supremo Tribunal Federal. Clovis, professor de Direito Constitucional, ao ouvir as afirmações de Ana, concluiu corretamente que','{"A": "todas estão certas.", "B": "todas estão erradas.", "C": "apenas a informação 2 está errada.", "D": "apenas as afirmações 2 e 3 estão erradas.", "E": "apenas as afirmações 1 e 3 estão erradas."}'::jsonb,'B',false,true,'SC','Controle','https://conhecimento.fgv.br/sites/default/files/concursos/cns104_-_auditor_do_estado_-_direito_manhacns104_tipo_1.pdf','https://conhecimento.fgv.br/sites/default/files/concursos/cgesc2022_gabarito_definitivo_retificado_20230327.pdf','conferir vigência da norma antes de ativar; disciplina atribuída pela ordem do caderno'),
('FGV','Controladoria-Geral do Estado de Santa Catarina','Auditor do Estado – Direito',2022,null,'Tipo 1',36,'Direito Constitucional',null,'O Chefe do Poder Executivo do Município Alfa foi informado por sua assessoria a respeito da necessidade de ser encaminhada a prestação de contas anual ao Tribunal de Contas. Ao questionar sua assessoria a respeito do papel desempenhado pelo Tribunal de Contas na análise das contas apresentadas, foi- lhe corretamente informado que esse órgão deve','{"A": "julgar as contas, quer sejam de gestão, quer de governo, sendo cabível recurso para a Câmara Municipal de Alfa.", "B": "apenas emitir parecer em relação às contas de governo e às contas de gestão, sendo que a Câmara Municipal de Alfa somente poderá rejeitá-lo pelo voto de dois terços dos seus membros.", "C": "julgar as contas de governo e emitir parecer prévio em relação às contas de gestão, não estando a Câmara Municipal de Alfa vinculada a este último, podendo acolhê-lo ou rejeitá- lo livremente.", "D": "julgar as contas de gestão e emitir parecer prévio em relação às contas de governo, sendo que a Câmara Municipal de Alfa somente poderá rejeitar este último pelo voto de três quintos dos seus membros.", "E": "julgar as contas de gestão e emitir parecer prévio em relação às contas de governo, sendo que a Câmara Municipal de Alfa somente poderá rejeitar este último pelo voto da maioria absoluta dos seus membros."}'::jsonb,'B',false,true,'SC','Controle','https://conhecimento.fgv.br/sites/default/files/concursos/cns104_-_auditor_do_estado_-_direito_manhacns104_tipo_1.pdf','https://conhecimento.fgv.br/sites/default/files/concursos/cgesc2022_gabarito_definitivo_retificado_20230327.pdf','conferir vigência da norma antes de ativar; disciplina atribuída pela ordem do caderno'),
('FGV','Controladoria-Geral do Estado de Santa Catarina','Auditor do Estado – Direito',2022,null,'Tipo 1',37,'Direito Constitucional',null,'Maria, estudante de Direito, questionou um professor a respeito da possibilidade de órgãos ou entidades da administração pública virem a ter subsidiárias, visando ao melhor cumprimento dos objetivos a que se destinam. O professor respondeu corretamente que','{"A": "somente a lei pode criar subsidiárias de órgãos ou entidades da administração pública.", "B": "somente a lei pode autorizar a criação de subsidiárias por órgãos ou entidades da administração pública.", "C": "a lei pode criar uma subsidiária de empresa pública, sendo que ambas integrarão a administração pública indireta.", "D": "a lei pode autorizar a criação de subsidiária de sociedade de economia mista, sendo que aquela não integrará a administração pública indireta.", "E": "as subsidiárias, entes da administração pública indireta, podem ser criadas a partir de autorização legal e estão sujeitas aos princípios regentes da administração pública."}'::jsonb,'X',false,true,'SC','Controle','https://conhecimento.fgv.br/sites/default/files/concursos/cns104_-_auditor_do_estado_-_direito_manhacns104_tipo_1.pdf','https://conhecimento.fgv.br/sites/default/files/concursos/cgesc2022_gabarito_definitivo_retificado_20230327.pdf','questão ANULADA pela banca; conferir vigência da norma antes de ativar; disciplina atribuída pela ordem do caderno'),
('FGV','Controladoria-Geral do Estado de Santa Catarina','Auditor do Estado – Direito',2022,null,'Tipo 1',38,'Direito Constitucional',null,'O Município Alfa, situado em localidade bucólica e muito procurado por pessoas que almejavam se afastar da agitação dos centros urbanos, editou a Lei nº XX. Esse diploma normativo estabeleceu a vedação de que correspondências fossem distribuídas e entregues nos horários que indicou, nos quais, conforme fora apurado em audiências públicas, grande parte dos munícipes preferia não ser incomodada. Em caso de descumprimento da vedação, seria aplicada a penalidade de multa e, na hipótese de reincidência, a de cassação do alvará. Irresignada com o teor da Lei nº XX, uma associação comercial situada no Município Alfa consultou um advogado a respeito de sua compatibilidade formal com a Constituição da República, sendo-lhe corretamente respondido que o referido diploma normativo é','{"A": "constitucional, pois o Município Alfa pode suplementar as normas editadas pela União e pelo Estado em matéria de proteção ao consumidor.", "B": "inconstitucional, pois compete privativamente à União legislar sobre o exercício de atividade econômica.", "C": "constitucional, pois trata de matéria tipicamente local, de competência legislativa do Município Alfa.", "D": "constitucional, pois é competência comum de todos os entes federativos zelar pela proteção à saúde.", "E": "inconstitucional, pois compete privativamente à União legislar sobre serviço postal."}'::jsonb,'E',false,true,'SC','Controle','https://conhecimento.fgv.br/sites/default/files/concursos/cns104_-_auditor_do_estado_-_direito_manhacns104_tipo_1.pdf','https://conhecimento.fgv.br/sites/default/files/concursos/cgesc2022_gabarito_definitivo_retificado_20230327.pdf','conferir vigência da norma antes de ativar; disciplina atribuída pela ordem do caderno'),
('FGV','Controladoria-Geral do Estado de Santa Catarina','Auditor do Estado – Direito',2022,null,'Tipo 1',39,'Direito Administrativo',null,'João, filiado ao Partido Político Alfa, foi eleito Deputado Federal. Logo após a proclamação dos eleitos, tomou conhecimento de que Alfa não alcançara a denominada “cláusula de desempenho”, prevista na Constituição da República de 1988. Preocupado com este fato, consultou um advogado a respeito da possibilidade de, após a sua posse, se desligar de Alfa e se filiar a outro partido político que tenha atingido a cláusula de desempenho, mas preservando o mandato obtido. O advogado respondeu corretamente que o objetivo alvitrado por João','{"A": "é amparado pela ordem constitucional, mas a nova filiação não será considerada para fins de distribuição dos recursos do fundo partidário e acesso gratuito ao tempo de rádio e de televisão.", "B": "não é amparado pela ordem constitucional, salvo se o não atingimento da “cláusula de desempenho” configurar justa causa, prevista em lei, o que permitirá o desligamento independente da aquiescência de Alfa.", "C": "é amparado pela ordem constitucional, desde que haja anuência de Alfa, e a nova filiação será considerada para fins de distribuição dos recursos do fundo partidário e acesso gratuito ao tempo de rádio e de televisão.", "D": "não é amparado pela ordem constitucional, pois, nas eleições proporcionais, o mandato é outorgado ao partido político, não ao candidato eleito, o que impede a filiação a novo partido político sem a perda do mandato.", "E": "não é amparado pela ordem constitucional, pois o não atingimento da “cláusula de desempenho” somente produz efeitos em relação ao funcionamento parlamentar na Casa legislativa, não tendo relação com o mandato de João. Direito Administrativo"}'::jsonb,'A',true,true,'SC','Controle','https://conhecimento.fgv.br/sites/default/files/concursos/cns104_-_auditor_do_estado_-_direito_manhacns104_tipo_1.pdf','https://conhecimento.fgv.br/sites/default/files/concursos/cgesc2022_gabarito_definitivo_retificado_20230327.pdf','depende de figura, tabela ou gráfico do caderno original: conferir antes de ativar; conferir vigência da norma antes de ativar; disciplina atribuída pela ordem do caderno'),
('FGV','Controladoria-Geral do Estado de Santa Catarina','Auditor do Estado – Direito',2022,null,'Tipo 1',40,'Direito Administrativo',null,'Em junho de 2020, João, ex-Secretário Estadual de Fazenda, foi condenado, com trânsito em julgado, pela prática de ato de improbidade administrativa que causou prejuízo ao erário, por ter, culposamente, concedido benefício administrativo ao particular Antônio, sem a observância das formalidades legais e regulamentares aplicáveis à espécie. Em janeiro de 2023, no bojo de processo de cumprimento de sentença, João alegou que as alterações promovidas pela Lei nº 14.230/21 na Lei de Improbidade Administrativa devem retroagir, pois não existe mais ato de improbidade culposo. No caso em tela, de acordo com a atual jurisprudência do Supremo Tribunal Federal, a tese de João','{"A": "não merece prosperar, pois exclusivamente os atos previstos na Lei de Improbidade que causam prejuízo ao erário ainda são puníveis na modalidade culposa.", "B": "não merece prosperar, pois a norma benéfica que revogou a modalidade culposa do ato de improbidade administrativa é irretroativa para os processos de execução das penas, pela eficácia da coisa julgada.", "C": "merece prosperar, pela aplicação do princípio da retroatividade da lei mais benéfica em matéria de direito sancionador, diante da indisponibilidade dos bens jurídicos tutelados pela lei de improbidade administrativa.", "D": "não merece prosperar, pelo princípio tempus regit actum, aplicando-se a regra da irretroatividade da lei e a preservação dos atos jurídicos perfeitos, seja para os processos de conhecimento em andamento, seja para os casos em que já houve trânsito em julgado.", "E": "merece prosperar, pelo princípio do in dubio pro reo que orienta a aplicação de normas relativas ao direito administrativo sancionador, haja vista que a nova lei dispõe que se aplicam ao sistema da improbidade os princípios constitucionais do direito administrativo sancionador."}'::jsonb,'B',false,true,'SC','Controle','https://conhecimento.fgv.br/sites/default/files/concursos/cns104_-_auditor_do_estado_-_direito_manhacns104_tipo_1.pdf','https://conhecimento.fgv.br/sites/default/files/concursos/cgesc2022_gabarito_definitivo_retificado_20230327.pdf','conferir vigência da norma antes de ativar; disciplina atribuída pela ordem do caderno'),
('FGV','Controladoria-Geral do Estado de Santa Catarina','Auditor do Estado – Direito',2022,null,'Tipo 1',41,'Direito Administrativo',null,'Em relação à delegação e à avocação da competência administrativa, de acordo com a Doutrina de Direito Administrativo e a Lei nº 9.784/99, é correto afirmar que','{"A": "a competência administrativa não pode ser objeto de delegação, mas pode ser de avocação.", "B": "a competência administrativa é renunciável nos casos de delegação e avocação legalmente admitidos.", "C": "a delegação não precisa ser específica, se admitindo a delegação genérica, desde que haja a devida publicação do ato no diário oficial.", "D": "podem ser objeto de delegação a edição de atos de caráter normativo, a decisão de recursos administrativos e as matérias de competência exclusiva do órgão ou autoridade.", "E": "não há, necessariamente, relação de verticalidade na delegação, mas o há na avocação, pois a lei estabelece a possibilidade de avocação temporária de competência atribuída a órgão hierarquicamente inferior."}'::jsonb,'E',false,true,'SC','Controle','https://conhecimento.fgv.br/sites/default/files/concursos/cns104_-_auditor_do_estado_-_direito_manhacns104_tipo_1.pdf','https://conhecimento.fgv.br/sites/default/files/concursos/cgesc2022_gabarito_definitivo_retificado_20230327.pdf','conferir vigência da norma antes de ativar; disciplina atribuída pela ordem do caderno'),
('FGV','Controladoria-Geral do Estado de Santa Catarina','Auditor do Estado – Direito',2022,null,'Tipo 1',42,'Direito Administrativo',null,'O Município Alfa pretende delegar, por lei, à sociedade de economia mista municipal Beta, empresa estatal municipal de capital social majoritariamente público, que presta exclusivamente serviço público de atuação própria do Estado e em regime não concorrencial, o poder de polícia de trânsito, inclusive quanto à aplicação de multas, em razão das atividades de policiamento do trânsito na cidade Alfa. No caso em tela, de acordo com a atual jurisprudência do Supremo Tribunal Federal, a delegação pretendida é','{"A": "constitucional, pois os atos de consentimento, de fiscalização e de aplicação de sanções podem ser delegados à estatal municipal Beta, por meio de lei.", "B": "constitucional, pois todas as fases do ciclo de polícia, inclusive a fase da ordem de polícia, podem ser delegadas a quaisquer entidades da administração indireta, em razão da supremacia do interesse público.", "C": "inconstitucional, pois nenhuma fase do ciclo de polícia pode ser objeto de delegação à pessoa jurídica de direito privado e eventual lei que assim dispuser será considerada inconstitucional.", "D": "inconstitucional, pois as fases do ciclo de polícia de atos de consentimento, de fiscalização e de aplicação de sanções não podem ser delegados à estatal Beta, que possui um regime jurídico complemente diverso daquele aplicável à Fazenda Pública.", "E": "constitucional, apenas se a delegação ocorrer por meio de emenda à Lei Orgânica Municipal, que pode promover legitimamente a delegação de todas as fases do ciclo de polícia à pessoa jurídica de direito privado integrante da administração indireta municipal."}'::jsonb,'A',false,true,'SC','Controle','https://conhecimento.fgv.br/sites/default/files/concursos/cns104_-_auditor_do_estado_-_direito_manhacns104_tipo_1.pdf','https://conhecimento.fgv.br/sites/default/files/concursos/cgesc2022_gabarito_definitivo_retificado_20230327.pdf','conferir vigência da norma antes de ativar; disciplina atribuída pela ordem do caderno'),
('FGV','Controladoria-Geral do Estado de Santa Catarina','Auditor do Estado – Direito',2022,null,'Tipo 1',43,'Direito Administrativo',null,'A Lei de Introdução às Normas do Direito Brasileiro estabelece que as autoridades públicas devem atuar para aumentar a segurança jurídica na aplicação das normas, inclusive por meio de regulamentos, súmulas administrativas e respostas a consultas. Neste contexto, de acordo com o citado diploma legal,','{"A": "tais instrumentos terão caráter vinculante em relação ao órgão ou entidade a que se destinam, até ulterior revisão.", "B": "tais instrumentos terão caráter de recomendação em relação ao órgão ou entidade a que se destinam, pelo prazo de 5 (cinco) anos, salvo se em prazo inferior houver revisão.", "C": "a decisão em processo administrativo não poderá impor compensação por benefícios indevidos ou prejuízos anormais ou injustos resultantes do processo ou da conduta dos envolvidos.", "D": "a edição de atos normativos por autoridade administrativa, salvo os de mera organização interna, não poderá ser precedida de consulta pública para manifestação de interessados, mas será objeto de ampla publicidade após a elaboração dos atos.", "E": "a revisão, na esfera administrativa, quanto à validade de ato cuja produção já se houver completado levará em conta as orientações gerais atuais, e não as da época, sendo permitido que, com base em mudança posterior de orientação geral, se declarem inválidas situações plenamente constituídas."}'::jsonb,'A',false,true,'SC','Controle','https://conhecimento.fgv.br/sites/default/files/concursos/cns104_-_auditor_do_estado_-_direito_manhacns104_tipo_1.pdf','https://conhecimento.fgv.br/sites/default/files/concursos/cgesc2022_gabarito_definitivo_retificado_20230327.pdf','conferir vigência da norma antes de ativar; disciplina atribuída pela ordem do caderno'),
('FGV','Controladoria-Geral do Estado de Santa Catarina','Auditor do Estado – Direito',2022,null,'Tipo 1',44,'Direito Administrativo',null,'O regime próprio de previdência social dos servidores titulares de cargos efetivos tem caráter contributivo e solidário, mediante contribuição do respectivo ente federativo, de servidores ativos, de aposentados e de pensionistas, observados critérios que preservem o equilíbrio financeiro e atuarial. Nesse contexto, de acordo com o atual texto da Constituição da República, o servidor abrangido por regime próprio de previdência social será aposentado','{"A": "compulsoriamente, com proventos proporcionais ao tempo de contribuição, necessariamente aos 70 (setenta) anos de idade, na forma de lei complementar.", "B": "por incapacidade permanente para o trabalho, no cargo em que estiver investido, quando suscetível de readaptação, hipótese em que será obrigatória a realização de avaliações periódicas anuais para verificação da continuidade das condições que ensejaram a concessão da aposentadoria, na forma de lei do respectivo ente federativo.", "C": "voluntariamente, desde que cumprido tempo mínimo de 10 (dez) anos de efetivo exercício no serviço público e cinco anos no cargo efetivo em que se dará a aposentadoria, bem como observada a idade de 65 (sessenta e cinco) anos, se homem, e 63 (sessenta e três) anos de idade, se mulher, com proventos proporcionais ao tempo de contribuição.", "D": "voluntariamente, desde que cumprido tempo mínimo de 10 (dez) anos de efetivo exercício no serviço público e cinco anos no cargo efetivo em que se dará a aposentadoria, bem como observada a idade de 60 (sessenta) anos de idade e 35 (trinta e cinco) de contribuição, se homem, e 55 (cinquenta e cinco) anos de idade e 35 (trinta e cinco) de contribuição, se mulher.", "E": "no âmbito da União, aos 62 (sessenta e dois) anos de idade, se mulher, e aos 65 (sessenta e cinco) anos de idade, se homem, e, no âmbito dos Estados, do Distrito Federal e dos Municípios, na idade mínima estabelecida mediante emenda às respectivas Constituições e Leis Orgânicas, observados o tempo de contribuição e os demais requisitos estabelecidos em lei complementar do respectivo ente federativo."}'::jsonb,'E',false,true,'SC','Controle','https://conhecimento.fgv.br/sites/default/files/concursos/cns104_-_auditor_do_estado_-_direito_manhacns104_tipo_1.pdf','https://conhecimento.fgv.br/sites/default/files/concursos/cgesc2022_gabarito_definitivo_retificado_20230327.pdf','conferir vigência da norma antes de ativar; disciplina atribuída pela ordem do caderno'),
('FGV','Controladoria-Geral do Estado de Santa Catarina','Auditor do Estado – Direito',2022,null,'Tipo 1',45,'Direito Administrativo',null,'O tratamento de dados pessoais cujo acesso é público deve considerar a finalidade, a boa-fé e o interesse público que justificaram sua disponibilização. Em tema de requisitos para o tratamento de dados pessoais, segundo a Lei Geral de Proteção de Dados Pessoais – LGPD), o tratamento de dados pessoais somente poderá ser realizado em algumas hipóteses. Essas hipóteses são apresentadas nas opções a seguir, à exceção de uma. Assinale-a.','{"A": "Proteção da vida ou da incolumidade física do titular ou de terceiro.", "B": "Cumprimento de obrigação legal ou regulatória pelo controlador.", "C": "Realização de estudos por órgão de pesquisa, garantida, sempre que possível, a anonimização dos dados pessoais.", "D": "Tutela da saúde em sentido amplo, sem exclusivamente em procedimento realizado por profissionais de saúde, serviços de saúde ou autoridade sanitária.", "E": "Necessidade para a execução de contrato ou de procedimentos preliminares relacionados a contrato do qual seja parte o titular, a pedido do titular dos dados."}'::jsonb,'D',false,true,'SC','Controle','https://conhecimento.fgv.br/sites/default/files/concursos/cns104_-_auditor_do_estado_-_direito_manhacns104_tipo_1.pdf','https://conhecimento.fgv.br/sites/default/files/concursos/cgesc2022_gabarito_definitivo_retificado_20230327.pdf','conferir vigência da norma antes de ativar; disciplina atribuída pela ordem do caderno'),
('FGV','Controladoria-Geral do Estado de Santa Catarina','Auditor do Estado – Direito',2022,null,'Tipo 1',46,'Direito Administrativo',null,'A Lei Complementar nº 741/2019 do Estado de Santa Catarina dispõe sobre a estrutura organizacional básica e o modelo de gestão da Administração Pública do Poder Executivo Estadual. Em matéria de estrutura organizacional do citado ente federativo, de acordo com a mencionada lei, a Controladoria- Geral do Estado (CGE) faz parte do(a)','{"A": "Gabinete do Vice-Governador do Estado.", "B": "Gabinete do Governador do Estado.", "C": "Procuradoria-Geral do Estado", "D": "Auditoria-Geral do Estado.", "E": "Conselho de Governo. Administração Financeira e Orçamentária"}'::jsonb,'B',false,true,'SC','Controle','https://conhecimento.fgv.br/sites/default/files/concursos/cns104_-_auditor_do_estado_-_direito_manhacns104_tipo_1.pdf','https://conhecimento.fgv.br/sites/default/files/concursos/cgesc2022_gabarito_definitivo_retificado_20230327.pdf','conferir vigência da norma antes de ativar; disciplina atribuída pela ordem do caderno'),
('FGV','Controladoria-Geral do Estado de Santa Catarina','Auditor do Estado – Direito',2022,null,'Tipo 1',47,'Contabilidade Pública',null,'Em uma entidade do setor público, os créditos referentes à dívida ativa devem ser inicialmente registrados','{"A": "no Ativo circulante.", "B": "no Passivo circulante.", "C": "no Ativo não circulante.", "D": "na Variação patrimonial.", "E": "no Passivo não circulante."}'::jsonb,'C',false,false,'SC','Controle','https://conhecimento.fgv.br/sites/default/files/concursos/cns104_-_auditor_do_estado_-_direito_manhacns104_tipo_1.pdf','https://conhecimento.fgv.br/sites/default/files/concursos/cgesc2022_gabarito_definitivo_retificado_20230327.pdf','disciplina atribuída pela ordem do caderno'),
('FGV','Controladoria-Geral do Estado de Santa Catarina','Auditor do Estado – Direito',2022,null,'Tipo 1',48,'Contabilidade Pública',null,'Em uma entidade do setor público, as despesas orçamentárias relacionadas a serviços de consultoria e a planejamento e execução de obras são classificados, respectivamente, como','{"A": "investimentos e investimentos.", "B": "outras despesas correntes e investimentos.", "C": "inversões financeiras e inversões financeiras.", "D": "outras despesas correntes e inversões financeiras.", "E": "outras despesas correntes e outras despesas correntes."}'::jsonb,'B',false,false,'SC','Controle','https://conhecimento.fgv.br/sites/default/files/concursos/cns104_-_auditor_do_estado_-_direito_manhacns104_tipo_1.pdf','https://conhecimento.fgv.br/sites/default/files/concursos/cgesc2022_gabarito_definitivo_retificado_20230327.pdf','disciplina atribuída pela ordem do caderno'),
('FGV','Controladoria-Geral do Estado de Santa Catarina','Auditor do Estado – Direito',2022,null,'Tipo 1',49,'Contabilidade Pública',null,'De acordo com o Manual de Contabilidade Aplicada ao Setor Público (MCASP), as receitas correntes intraorçamentárias e as receitas de capital intraorçamentárias foram incluídas nas categorias econômicas da receita corrente e de receita de capital, com a finalidade de','{"A": "criar novas categorias econômicas de receita corrente e de receita de capital.", "B": "evitar a dupla contagem dos valores financeiros objeto de operações intraorçamentárias na consolidação das contas públicas.", "C": "representar a contrapartida das despesas classificadas como inversões financeiras.", "D": "diferenciar a destinação das multas da dívida ativa da destinação dos juros de mora da dívida ativa.", "E": "registrar as operações realizadas entre órgãos e demais entidades da Administração Pública que integram o orçamento fiscal e o orçamento da seguridade social de entes federativos distintos."}'::jsonb,'B',false,false,'SC','Controle','https://conhecimento.fgv.br/sites/default/files/concursos/cns104_-_auditor_do_estado_-_direito_manhacns104_tipo_1.pdf','https://conhecimento.fgv.br/sites/default/files/concursos/cgesc2022_gabarito_definitivo_retificado_20230327.pdf','disciplina atribuída pela ordem do caderno'),
('FGV','Controladoria-Geral do Estado de Santa Catarina','Auditor do Estado – Direito',2022,null,'Tipo 1',50,'Contabilidade Pública',null,'Com relação à dedução de receita orçamentária, considere os itens a seguir: I. Renúncia de receita orçamentária. II. Restituição de receitas recebidas a maior ou indevidamente. III. Recursos que o ente tenha a competência de arrecadar, mas que pertencem a outro ente, de acordo com a legislação vigente. No âmbito da administração pública, e salvo a existência de determinação legal contrária, a dedução de receita orçamentária é o procedimento padrão a ser usado em','{"A": "II, apenas.", "B": "I e II, apenas.", "C": "I e III, apenas.", "D": "II e III, apenas.", "E": "I, II e III."}'::jsonb,'E',false,false,'SC','Controle','https://conhecimento.fgv.br/sites/default/files/concursos/cns104_-_auditor_do_estado_-_direito_manhacns104_tipo_1.pdf','https://conhecimento.fgv.br/sites/default/files/concursos/cgesc2022_gabarito_definitivo_retificado_20230327.pdf','disciplina atribuída pela ordem do caderno'),
('FGV','Controladoria-Geral do Estado de Santa Catarina','Auditor do Estado – Direito',2022,null,'Tipo 1',51,'Administração Financeira e Orçamentária',null,'De acordo com a Lei nº 10.180/2001, o Sistema de Planejamento e de Orçamento Federal compreende as atividades de elaboração, acompanhamento e avaliação de planos, programas e orçamentos, e de realização de estudos e pesquisas socioeconômicas. Integram o Sistema de Planejamento e de Orçamento Federal, o Ministério do Planejamento, Orçamento e Gestão, como órgão central, os órgãos setoriais e os órgãos específicos. Em relação aos órgãos setoriais e específicos, assinale a afirmativa correta.','{"A": "Os órgãos setoriais e específicos ficam sujeitos à orientação normativa e à supervisão técnica do órgão em cuja estrutura administrativa estiverem integrados.", "B": "Os órgãos setoriais são aqueles vinculados ou subordinados ao órgão central do Sistema, cuja missão está voltada para as atividades de planejamento e orçamento.", "C": "Os órgãos específicos são as unidades de planejamento e orçamento dos Ministérios, da Advocacia-Geral da União, da Vice-Presidência e da Casa Civil da Presidência da República.", "D": "O órgão setorial da Casa Civil da Presidência da República tem como área de atuação todos os órgãos integrantes da Presidência da República, ressalvados outros determinados em legislação específica.", "E": "As unidades de planejamento e orçamento das entidades vinculadas aos Ministérios e órgãos setoriais ficam sujeitas à orientação normativa e à supervisão técnica exclusiva do respectivo órgão setorial."}'::jsonb,'D',false,false,'SC','Controle','https://conhecimento.fgv.br/sites/default/files/concursos/cns104_-_auditor_do_estado_-_direito_manhacns104_tipo_1.pdf','https://conhecimento.fgv.br/sites/default/files/concursos/cgesc2022_gabarito_definitivo_retificado_20230327.pdf','disciplina atribuída pela ordem do caderno'),
('FGV','Controladoria-Geral do Estado de Santa Catarina','Auditor do Estado – Direito',2022,null,'Tipo 1',52,'Administração Financeira e Orçamentária',null,'Os procedimentos previstos na Lei nº 12.527/2011 destinam-se a assegurar o direito fundamental de acesso à informação e devem ser executados em conformidade com os seguintes princípios básicos da Administração Pública e diretrizes, à exceção de um. Assinale-o.','{"A": "Desenvolvimento do controle social da Administração Pública.", "B": "Observância da publicidade como preceito geral e do sigilo como exceção.", "C": "Fomento ao desenvolvimento da cultura de transparência na Administração Pública.", "D": "Uso de meios de comunicação viabilizados pela tecnologia da informação.", "E": "Divulgação de informações de interesse público condicionada à solicitação de requerente."}'::jsonb,'E',false,false,'SC','Controle','https://conhecimento.fgv.br/sites/default/files/concursos/cns104_-_auditor_do_estado_-_direito_manhacns104_tipo_1.pdf','https://conhecimento.fgv.br/sites/default/files/concursos/cgesc2022_gabarito_definitivo_retificado_20230327.pdf','disciplina atribuída pela ordem do caderno'),
('FGV','Controladoria-Geral do Estado de Santa Catarina','Auditor do Estado – Direito',2022,null,'Tipo 1',53,'Legislação de Controle Interno',null,'De acordo com a Lei nº 12.527/2011, a pessoa física ou entidade privada que detiver informações em virtude de vínculo de qualquer natureza com o poder público e deixar de observar o disposto na Lei estará sujeita a sanções. Assegurado o direito de defesa do interessado, as sanções representadas por advertência e rescisão do vínculo com o poder público poderão ser aplicadas juntamente com','{"A": "multa.", "B": "reclusão.", "C": "suspensão temporária de participar em licitação.", "D": "impedimento de contratar com a Administração Pública.", "E": "declaração de inidoneidade para licitar ou contratar com a Administração Pública. Administração Pública e Políticas Públicas"}'::jsonb,'A',false,true,'SC','Controle','https://conhecimento.fgv.br/sites/default/files/concursos/cns104_-_auditor_do_estado_-_direito_manhacns104_tipo_1.pdf','https://conhecimento.fgv.br/sites/default/files/concursos/cgesc2022_gabarito_definitivo_retificado_20230327.pdf','conferir vigência da norma antes de ativar; disciplina atribuída pela ordem do caderno'),
('FGV','Controladoria-Geral do Estado de Santa Catarina','Auditor do Estado – Direito',2022,null,'Tipo 1',54,'Legislação de Controle Interno',null,'Avalie se as afirmativas a seguir estão em consonância com os princípios fundamentais da Administração Pública: I. Na Administração Pública não há liberdade nem vontade pessoal, de modo que é lícito fazer tudo que a lei não proíbe. II. Os atos dos funcionários públicos são sempre imputados ao órgão para o qual oficiam, de forma que o ato de um agente é na verdade o ato de um órgão. III. Todo ato administrativo deve ser publicado, com exceção dos que possuem sigilo nos casos de segurança nacional, investigações policiais ou de interesse superior da Administração, conforme previstos na lei. Está correto o que se afirma em','{"A": "I, apenas.", "B": "I e II, apenas.", "C": "I e III, apenas.", "D": "II e III, apenas.", "E": "I, II e III."}'::jsonb,'D',false,true,'SC','Controle','https://conhecimento.fgv.br/sites/default/files/concursos/cns104_-_auditor_do_estado_-_direito_manhacns104_tipo_1.pdf','https://conhecimento.fgv.br/sites/default/files/concursos/cgesc2022_gabarito_definitivo_retificado_20230327.pdf','conferir vigência da norma antes de ativar; disciplina atribuída pela ordem do caderno'),
('FGV','Controladoria-Geral do Estado de Santa Catarina','Auditor do Estado – Direito',2022,null,'Tipo 1',55,'Administração Pública',null,'Primeira das funções administrativas, o planejamento é um processo de estabelecer objetivos e definir a maneira como alcançá-los. Como principal decorrência do planejamento estão os planos, que facilitam a organização para alcançar suas metas e objetivos. Com relação aos planos, assinale (V) para a afirmativa verdadeira e (F) para a falsa. ( ) Servem para segregar os vários objetivos a serem alcançados em um esquema organizacional que proporciona coordenação e integração. ( ) Definem os recursos necessários para alcançar os objetivos organizacionais. ( ) Permitem que as pessoas trabalhem em diferentes atividades consistentes com os objetivos definidos. As afirmativas são, respectivamente,','{"A": "F, V e F.", "B": "V, F e F.", "C": "F, V e V.", "D": "V, V e F.", "E": "V, F e V."}'::jsonb,'C',false,false,'SC','Controle','https://conhecimento.fgv.br/sites/default/files/concursos/cns104_-_auditor_do_estado_-_direito_manhacns104_tipo_1.pdf','https://conhecimento.fgv.br/sites/default/files/concursos/cgesc2022_gabarito_definitivo_retificado_20230327.pdf','disciplina atribuída pela ordem do caderno'),
('FGV','Controladoria-Geral do Estado de Santa Catarina','Auditor do Estado – Direito',2022,null,'Tipo 1',56,'Administração Pública',null,'A abordagem administrativa da gestão de processos é também conhecida como abordagem sistêmica para gestão das organizações, baseando-se na Teoria Geral dos Sistemas (TGS). A TGS surgiu como uma crítica à abordagem científica e reducionista, predominante na época, que reduzia as entidades para o estudo individual de suas propriedades e de suas partes ou elementos. No vocabulário técnico da gestão de processos, a declaração de políticas e práticas que determinam o que é possível, desejável ou mesmo impossível na operação do negócio, é denominada','{"A": "evento de negócio.", "B": "regra de negócio.", "C": "escopo do processo.", "D": "fluxo do trabalho do processo.", "E": "transação de negócio."}'::jsonb,'B',false,false,'SC','Controle','https://conhecimento.fgv.br/sites/default/files/concursos/cns104_-_auditor_do_estado_-_direito_manhacns104_tipo_1.pdf','https://conhecimento.fgv.br/sites/default/files/concursos/cgesc2022_gabarito_definitivo_retificado_20230327.pdf','disciplina atribuída pela ordem do caderno'),
('FGV','Controladoria-Geral do Estado de Santa Catarina','Auditor do Estado – Direito',2022,null,'Tipo 1',57,'Administração Pública',null,'Nos últimos anos, mudanças significativas nos padrões de vida, comportamentos e expectativas têm produzido um pronunciado efeito no comportamento das pessoas nas organizações. A consequência desse processo evolutivo é a constante evolução e adequação das estruturas de gestão, que, cada vez mais, acontecem de forma mais rápida, muito em função das necessidades de mudança provocadas pelos ambientes nos quais as organizações estão inseridas. Sobre a gestão de projetos, analise as afirmativas a seguir: I. O patrocinador do projeto é responsável pela ligação entre estruturas internas e externas do projeto. II. O gerente do projeto é um membro da alta gerência da organização que tem interesse real e autoriza formalmente o projeto. III. Muitas estruturas externas são formadas por circunstâncias que escapam ao controle do gerente do projeto. Está correto o que se afirma em','{"A": "I, II e III.", "B": "I e II, apenas.", "C": "I e III, apenas.", "D": "II, apenas.", "E": "III, apenas."}'::jsonb,'E',false,false,'SC','Controle','https://conhecimento.fgv.br/sites/default/files/concursos/cns104_-_auditor_do_estado_-_direito_manhacns104_tipo_1.pdf','https://conhecimento.fgv.br/sites/default/files/concursos/cgesc2022_gabarito_definitivo_retificado_20230327.pdf','disciplina atribuída pela ordem do caderno'),
('FGV','Controladoria-Geral do Estado de Santa Catarina','Auditor do Estado – Direito',2022,null,'Tipo 1',58,'Administração Pública',null,'O processo de elaboração de políticas públicas também é conhecido como ciclo de políticas públicas. Este é um esquema de visualização e interpretação que organiza a vida de uma política pública em fases sequenciais e interdependentes. Relacione as fases do ciclo de políticas públicas com suas respectivas definições. 1. Formação da Agenda 2. Tomada de Decisão 3. Avaliação da política pública ( ) Processo de julgamentos deliberados sobre a validade de propostas para a ação pública, bem como sobre o sucesso ou a falha de projetos que foram colocados em prática. ( ) Conjunto de problemas que a comunidade política percebe como merecedor de intervenção pública. ( ) Momento em que os interesses dos atores são equacionados e as intenções de enfrentamento de um problema público são explicitadas. Assinale a opção que indica a relação correta na ordem apresentada.','{"A": "3, 1 e 2.", "B": "3, 2 e 1.", "C": "2, 1 e 3.", "D": "1, 3 e 2.", "E": "1, 2 e 3."}'::jsonb,'A',false,false,'SC','Controle','https://conhecimento.fgv.br/sites/default/files/concursos/cns104_-_auditor_do_estado_-_direito_manhacns104_tipo_1.pdf','https://conhecimento.fgv.br/sites/default/files/concursos/cgesc2022_gabarito_definitivo_retificado_20230327.pdf','disciplina atribuída pela ordem do caderno'),
('FGV','Controladoria-Geral do Estado de Santa Catarina','Auditor do Estado – Direito',2022,null,'Tipo 1',59,'Administração Pública',null,'A avaliação é a fase do ciclo de políticas públicas em que o processo de implementação e o desempenho da política pública são examinados com o intuito de conhecer melhor o estado da política e o nível de redução do problema que a gerou. É o momento-chave para a produção de feedback sobre as fases antecedentes. Com relação à avaliação de políticas públicas, assinale (V) para a afirmativa verdadeira e (F) para a falsa. ( ) A avaliação de uma política pública compreende a definição de critérios, indicadores e padrões (performance standards). ( ) O critério da eficiência administrativa corresponde ao nível de conformidade (compliance) da implementação a regras preestabelecidas. ( ) O critério de produtividade corresponde aos resultados sociais (outcomes) com a redução do problema e a geração de valor para a população. As afirmativas são, respectivamente,','{"A": "F, V e F.", "B": "F, V e V.", "C": "V, F e F.", "D": "V, V e F.", "E": "V, F e V."}'::jsonb,'D',false,false,'SC','Controle','https://conhecimento.fgv.br/sites/default/files/concursos/cns104_-_auditor_do_estado_-_direito_manhacns104_tipo_1.pdf','https://conhecimento.fgv.br/sites/default/files/concursos/cgesc2022_gabarito_definitivo_retificado_20230327.pdf','disciplina atribuída pela ordem do caderno'),
('FGV','Controladoria-Geral do Estado de Santa Catarina','Auditor do Estado – Direito',2022,null,'Tipo 1',60,'Administração Pública',null,'Pesquisas internacionais indicam que o fim da impunidade é uma medida necessária para acabar com o círculo vicioso de corrupção nas esferas privada e pública. Recentemente, promotores do Ministério Público Federal elaboraram as “10 Medidas Contra a Corrupção”, uma proposta para endurecer o sistema punitivo de crimes contra a Administração Pública, a criminalização do caixa 2 nas campanhas eleitorais, a punição contra juízes e promotores que cometerem ilícitos, entre outras medidas. Sobre os fatores que influenciam a incidência de corrupção e fatores que promovem a qualidade das políticas públicas, analise os itens a seguir. I. A independência funcional perante os poderes Executivo, Legislativo e Judiciário permite que o Ministério Público possa servir como guardião do correto funcionamento da Administração Pública e da Justiça. II. A mídia exerce papel de controle sobre a esfera política e a atuação da Administração Pública, realizando jornalismo investigativo, denunciando corrupção e apontando as melhores práticas. III. Implícita na visão weberiana está a interpretação de que o trabalho do burocrata deve ter suma discricionariedade, de forma a evitar corrupção, favoritismos ou desvirtuamentos dos interesses coletivos. Está correto o que se afirma em','{"A": "I, II e III.", "B": "I e II, apenas.", "C": "I e III, apenas.", "D": "III, apenas.", "E": "I, apenas. Prova Discursiva (Redação) Atualmente, é mais do que comum ver em manchetes de revistas e jornais que a polícia conseguiu prender mais uma quadrilha de sonegadores fiscais. O crime de sonegação fiscal, previsto na Lei 8.137/90, é um dos crimes que afeta o Estado de forma mais drástica, uma vez que o dinheiro que deixou de ser arrecadado seria utilizado na realização de projetos sociais e outras finalidades do Estado. Segundo o art. 3º do CTN, “tributo é toda prestação pecuniária compulsória, em moeda ou cujo valor nela se possa exprimir, que não constitua sansão de ato ilícito, instituída em lei e cobrada mediante atividade administrativa plenamente vinculada”. O bem jurídico tutelado nos crimes de sonegação fiscal é a arrecadação tributária, sendo o sujeito ativo nesses crimes, em regra, o contribuinte ou o responsável (caso a lei preveja substituição tributária), podendo, excepcionalmente, ser qualquer pessoa, como nos casos do art. 2°, III e V da Lei 8.137/90. O sujeito passivo será sempre um dos entes da Federação (União Federal, estados, municípios ou Distrito Federal). (Jus.com.br) Nesse segmento textual há uma referência a um dos problemas brasileiros mais graves: a sonegação fiscal, com reflexos em quase todas as áreas da vida nacional. Num texto dissertativo-argumentativo, em língua culta, de 40 a 60 linhas, expresse sua visão do problema, mostrando a sua gravidade e as medidas que podem ser tomadas para reduzi-lo. 1 ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------- 2 ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------- 3 ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------- 4 ---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------- 5 -----------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------